TEXT        = (232, 234, 244)
TEXT_DIM    = (178, 184, 206)   # v3.23: eski (150,155,178) koyu panelde okunmuyordu
GOLD        = (232, 186, 90)
GOLD_DIM    = (150, 120, 65)
RED         = (232, 90, 100)
GREEN       = (110, 220, 140)
BLUE        = (100, 160, 240)
PURPLE      = (170, 120, 230)
