_font_cache = {}
_text_cache = {}


# =====================================================================
# OKUNABİLİRLİK TABANI  (v3.23)
# ---------------------------------------------------------------------
# Oyuncu: "bazı yazılar okunmuyor, bunun gibi çok yazı var." Haklıydı:
# 407 yazı çağrısının 152'si 11 puntonun altındaydı, 84'ü 10 ve altı.
# 1280x720'lik sanal tuvalde 9-10 punto, pencere küçükken gerçekten
# kayboluyor. Artık TEK BİR KAPIDAN geçiyor: draw_text ve text_width bu
# tabanın altına inmiyor, yani ÖLÇÜ ile ÇİZİM her zaman aynı puntoyu
# kullanıyor (ortalama ve satır kaydırma kaymıyor).
#
# tiny=True isteyen yerler tabanı atlar — dünyada uçuşan hasar sayıları
# gibi, küçüklüğü bilerek seçilmiş birkaç yer için.
UI_MIN_FONT = 12


def ui_font_size(size, tiny=False):
    """Yazı puntosunu okunabilirlik tabanına yükseltir."""
    size = int(size)
    if tiny or size >= UI_MIN_FONT:
        return size
    return UI_MIN_FONT


def get_font(size, bold=False):
    size = int(size)
    key = (size, bold)
    f = _font_cache.get(key)
    if f is None:
        try:
            f = pygame.font.SysFont("segoeui,arial,helvetica,sans", size, bold=bold)
        except Exception:
            f = pygame.font.Font(None, size)
        _font_cache[key] = f
    return f


def _render(text, size, bold, color):
    key = (text, size, bold, color)
    img = _text_cache.get(key)
    if img is None:
        if len(_text_cache) > 900:
            _text_cache.clear()
        img = get_font(size, bold).render(text, True, color)
        _text_cache[key] = img
    return img


def draw_text(surf, text, pos, size=20, color=TEXT, bold=False,
              center=False, shadow=True, alpha=255, right=False, tiny=False):
    size = ui_font_size(size, tiny)
    color = (int(color[0]), int(color[1]), int(color[2]))
    alpha = int(clamp(alpha, 0, 255))
    img = _render(text, size, bold, color)
    img.set_alpha(alpha)
    r = img.get_rect()
    px, py = int(pos[0]), int(pos[1])
    if center:
        r.center = (px, py)
    elif right:
        r.topright = (px, py)
    else:
        r.topleft = (px, py)
    if shadow:
        sh = _render(text, size, bold, (0, 0, 0))
        sh.set_alpha(alpha)
        surf.blit(sh, (r.x + 2, r.y + 2))
    surf.blit(img, r)
    return r


def text_width(text, size=20, bold=False, tiny=False):
    return get_font(ui_font_size(size, tiny), bold).size(text)[0]


def text_height(size, bold=False, tiny=False):
    """Bir satırın kapladığı yükseklik — satır aralığı hesapları için."""
    return get_font(ui_font_size(size, tiny), bold).get_height()


def wrap_text(text, size, max_w, bold=False):
    words = text.split(" ")
    lines, line = [], ""
    for w in words:
        test = (line + " " + w).strip()
        if text_width(test, size, bold) > max_w and line:
            lines.append(line)
            line = w
        else:
            line = test
    if line:
        lines.append(line)
    return lines


def wrap_clip(text, size, max_w, lines, bold=False):
    """Satırlara böler, en çok `lines` satır döndürür ve KESİLDİĞİNİ belli eder.

    Eskiden fazlası sessizce atılıyordu: kart "...birkaç seviyede" diye
    cümlenin ortasında bitiyor, oyuncu yazının bozuk olduğunu sanıyordu.
    Artık son satır "…" ile biter — devamı olduğu anlaşılır (tamamı ayrıntı
    ekranında zaten yazıyor).
    """
    out = wrap_text(text, size, max_w, bold)
    if len(out) <= lines:
        return out
    out = out[:lines]
    son = out[-1]
    while son and text_width(son + "…", size, bold) > max_w:
        son = son[:-1]
    out[-1] = son.rstrip() + "…"
    return out


# =====================================================================
# GLOW / DISK / GÖLGE ÖNBELLEKLERİ  (performans için sprite kullanılır)
# =====================================================================
_glow_cache = {}
_disc_cache = {}
_shadow_cache = {}


def glow_sprite(r, color, level):
    key = (r, color, level)
    s = _glow_cache.get(key)
    if s is None:
        if len(_glow_cache) > 1400:
            _glow_cache.clear()
        s = pygame.Surface((r * 2, r * 2))
        s.fill((0, 0, 0))
        steps = int(min(26, max(5, r // 2 + 3)))
        k = level / 8.0
        for i in range(steps):
            f = i / (steps - 1)
            rad = max(1, int(r * (1 - f * 0.94)))
            inten = (f ** 2.3) * k
            pygame.draw.circle(s, scale_col(color, inten), (r, r), rad)
        _glow_cache[key] = s
    return s


_glow_cache_a = {}


def glow_sprite_alpha(r, color, level):
    """SAYDAM yüzeye basılabilen parlama.

    Normal parlama opak zemine TOPLAMALI basılır; saydam bir yüzeyde ise
    alfa 0 kaldığı için hiç görünmez. Burada alfa da yarıçapla birlikte
    sönüyor, böylece önbelleğe alınmış bir sprite'ın içindeki parlama,
    sprite dünyaya basıldığında yumuşak bir hâle olarak çıkıyor.
    """
    key = (r, color, level)
    s = _glow_cache_a.get(key)
    if s is None:
        if len(_glow_cache_a) > 900:
            _glow_cache_a.clear()
        s = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
        steps = int(min(26, max(5, r // 2 + 3)))
        k = level / 8.0
        for i in range(steps):
            f = i / (steps - 1)
            rad = max(1, int(r * (1 - f * 0.94)))
            inten = (f ** 2.3) * k
            # DİKKAT: renk TAM parlaklıkta, sönümleme YALNIZCA alfada.
            # Hem rengi hem alfayı sönümlersek katkı inten² olur ve hâle
            # neredeyse kaybolur (toplamalı sürümde katkı inten'dir).
            pygame.draw.circle(s, (color[0], color[1], color[2],
                                   int(clamp(255 * inten, 0, 255))), (r, r), rad)
        _glow_cache_a[key] = s
    return s


# Saydam bir ara yüzeye (simge / yaratık gövdesi önbelleği) çizerken açılır.
_GLOW_ON_ALPHA = False


def add_glow(surf, x, y, r, color, k=1.0):
    """Parlama. Opak zeminde toplamalı, saydam yüzeyde alfalı."""
    level = int(clamp(k, 0.0, 1.0) * 8 + 0.5)
    if level <= 0:
        return
    r = max(2, int(r) // 2 * 2)
    c = (int(color[0]), int(color[1]), int(color[2]))
    pos = (int(x - r), int(y - r))
    if _GLOW_ON_ALPHA:
        # Saydam yüzeyde NORMAL alfa karışımı kullanılır. Toplamalı karışım
        # alfaya değil doğrudan RGB'ye eklediği için gövdeyi beyaza boğuyordu.
        surf.blit(glow_sprite_alpha(r, c, level), pos)
    else:
        surf.blit(glow_sprite(r, c, level), pos,
                  special_flags=pygame.BLEND_RGB_ADD)


def disc_sprite(r, color, alpha):
    a = int(clamp(alpha, 0, 255)) // 16 * 16
    key = (r, color, a)
    s = _disc_cache.get(key)
    if s is None:
        if len(_disc_cache) > 1400:
            _disc_cache.clear()
        s = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
        pygame.draw.circle(s, (color[0], color[1], color[2], a), (r, r), r)
        _disc_cache[key] = s
    return s


def blit_disc(surf, x, y, r, color, alpha):
    r = max(1, int(r))
    if r > 14:
        r = r // 4 * 4
    if alpha < 8:
        return
    sp = disc_sprite(r, (int(color[0]), int(color[1]), int(color[2])), alpha)
    surf.blit(sp, (int(x - r), int(y - r)))


def shadow_sprite(w):
    w = max(6, int(w) // 2 * 2)
    s = _shadow_cache.get(w)
    if s is None:
        s = pygame.Surface((w, max(4, w // 3)), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (0, 0, 0, 95), s.get_rect())
        _shadow_cache[w] = s
    return s


def draw_bar(surf, rect, frac, color, bg=(28, 30, 44), border=PANEL_EDGE, radius=7):
    rect = pygame.Rect(rect)
    pygame.draw.rect(surf, bg, rect, border_radius=radius)
    frac = clamp(frac, 0.0, 1.0)
    w = int((rect.w - 4) * frac)
    if w > 2:
        inner = pygame.Rect(rect.x + 2, rect.y + 2, w, rect.h - 4)
        pygame.draw.rect(surf, color, inner, border_radius=max(2, radius - 2))
        hl = pygame.Rect(inner.x + 2, inner.y + 1, max(1, inner.w - 4), max(1, inner.h // 3))
        pygame.draw.rect(surf, lighten(color, 0.4), hl, border_radius=3)
    pygame.draw.rect(surf, border, rect, width=2, border_radius=radius)


# =====================================================================
# SES  (tamamen kod ile sentezlenir — dış dosya gerekmez)
# =====================================================================
_SR = 22050


# =====================================================================
# YUMUŞAK KENARLI ÇİZİM YARDIMCILARI
# ---------------------------------------------------------------------
# pygame.draw.polygon / line kenarları basamaklı bırakıyor: küçük simgeler
# bu yüzden "pixel art" gibi görünüyordu. Aşağıdaki yardımcılar gfxdraw ile
# kenarı yumuşatır ve üst üste birkaç ton koyarak yüzeye HACİM kazandırır
# (koyu kontur -> gövde -> pah ışığı -> keskin parlama).
#
# Hepsi DOĞRUDAN hedef yüzeye çizer: her simge için geçici SRCALPHA yüzeyi
# ayırmak menülerde kare süresini gereksiz yere yiyordu.
# =====================================================================


def _ipts(pts):
    return [(int(round(x)), int(round(y))) for x, y in pts]


def poly_aa(surf, pts, col):
    """Kenarı yumuşatılmış DOLU çokgen."""
    if len(pts) < 3:
        return
    ip = _ipts(pts)
    if _gfx is not None:
        try:
            _gfx.filled_polygon(surf, ip, col)
            _gfx.aapolygon(surf, ip, col)
            return
        except Exception:
            pass
    pygame.draw.polygon(surf, col, ip)


def poly_edge(surf, pts, col, w=1):
    """Kenarı yumuşatılmış çokgen ÇERÇEVESİ."""
    if len(pts) < 3:
        return
    ip = _ipts(pts)
    if w <= 1 and _gfx is not None:
        try:
            _gfx.aapolygon(surf, ip, col)
            return
        except Exception:
            pass
    pygame.draw.polygon(surf, col, ip, max(1, int(w)))


def circle_aa(surf, cx, cy, r, col):
    """Kenarı yumuşatılmış DOLU daire."""
    r = int(round(r))
    if r < 1:
        return
    cx, cy = int(round(cx)), int(round(cy))
    if _gfx is not None:
        try:
            _gfx.filled_circle(surf, cx, cy, r, col)
            _gfx.aacircle(surf, cx, cy, r, col)
            return
        except Exception:
            pass
    pygame.draw.circle(surf, col, (cx, cy), r)


def ring_aa(surf, cx, cy, r, col, w=1):
    """Kenarı yumuşatılmış çember (içi boş)."""
    r = int(round(r))
    if r < 1:
        return
    if w <= 1 and _gfx is not None:
        try:
            _gfx.aacircle(surf, int(round(cx)), int(round(cy)), r, col)
            return
        except Exception:
            pass
    pygame.draw.circle(surf, col, (int(round(cx)), int(round(cy))), r, max(1, int(w)))


def disc_grad(surf, cx, cy, r, inner, outer, steps=10):
    """Merkezden kenara doğru renk geçişli daire (madalyon tabanı gibi)."""
    for i in range(steps, 0, -1):
        f = i / float(steps)
        circle_aa(surf, cx, cy, r * f, mix_col(inner, outer, f))


def poly_inset(pts, k, dx=0.0, dy=0.0):
    """Çokgeni merkezine doğru k oranında küçültür (pah/bizote katmanı için)."""
    n = float(len(pts))
    cx = sum(p[0] for p in pts) / n
    cy = sum(p[1] for p in pts) / n
    return [(cx + (x - cx) * k + dx, cy + (y - cy) * k + dy) for x, y in pts]


def thick_line(surf, p0, p1, w, col, cap=True):
    """Kenarı yumuşak KALIN çizgi — pygame.draw.line'ın basamaklı hâli yerine."""
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    ln = math.hypot(dx, dy)
    if ln < 1e-4 or w <= 0:
        return
    nx, ny = -dy / ln * w * 0.5, dx / ln * w * 0.5
    poly_aa(surf, [(p0[0] + nx, p0[1] + ny), (p1[0] + nx, p1[1] + ny),
                   (p1[0] - nx, p1[1] - ny), (p0[0] - nx, p0[1] - ny)], col)
    if cap and w > 3:
        circle_aa(surf, p0[0], p0[1], w * 0.5, col)
        circle_aa(surf, p1[0], p1[1], w * 0.5, col)


def taper_line(surf, pts, w0, w1, col0, col1=None):
    """Kalınlığı ve rengi uçtan uca değişen yumuşak şerit (kırbaç, alev dili)."""
    col1 = col1 or col0
    n = len(pts)
    for i in range(n - 1):
        f = i / max(1.0, n - 2.0)
        thick_line(surf, pts[i], pts[i + 1], lerp(w0, w1, f),
                   mix_col(col0, col1, f))


def metal(surf, pts, base, lite=None, dark=None, spec=True, ow=2.0, lx=-0.45, ly=-0.55):
    """ÇELİK yüzey: kontur + gövde + pah ışığı + keskin parlama.

    Tek renk düz dolgu yerine üç ton üst üste konunca yüzey hacim kazanıyor;
    (lx, ly) ışığın geldiği yön — pah katmanı o yöne kayar.
    """
    lite = lite or lighten(base, 0.58)
    dark = dark or scale_col(base, 0.42)
    poly_aa(surf, [(x, y + max(1.0, ow * 0.9)) for x, y in pts], OUTLINE)
    poly_aa(surf, pts, dark)
    poly_aa(surf, poly_inset(pts, 0.93), base)
    poly_aa(surf, poly_inset(pts, 0.58, dx=lx * ow * 1.6, dy=ly * ow * 1.6), lite)
    if spec:
        poly_aa(surf, poly_inset(pts, 0.24, dx=lx * ow * 2.4, dy=ly * ow * 2.4), WHITE)
    poly_edge(surf, pts, scale_col(base, 0.70), max(1, int(ow * 0.6)))


def wood_shaft(surf, p0, p1, w, base=(152, 106, 62)):
    """AHŞAP sap: koyu kontur + gövde + damar + üst kenarda ışık."""
    dark = scale_col(base, 0.44)
    lite = lighten(base, 0.42)
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    ln = math.hypot(dx, dy) or 1.0
    nx, ny = -dy / ln, dx / ln
    thick_line(surf, p0, p1, w + 3.0, OUTLINE)
    thick_line(surf, p0, p1, w, dark)
    off = w * 0.14
    thick_line(surf, (p0[0] + nx * off, p0[1] + ny * off),
               (p1[0] + nx * off, p1[1] + ny * off), w * 0.66, base)
    off2 = -w * 0.26
    thick_line(surf, (p0[0] + nx * off2, p0[1] + ny * off2),
               (p1[0] + nx * off2, p1[1] + ny * off2), max(1.0, w * 0.20), lite)


def leather_wrap(surf, p0, p1, w, n=4, base=(96, 62, 44)):
    """Kabza sargısı: sapın üstüne çapraz deri şeritler."""
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    ln = math.hypot(dx, dy) or 1.0
    ux, uy = dx / ln, dy / ln
    nx, ny = -uy, ux
    seg = ln / (n + 0.6)
    for i in range(n):
        s = (i + 0.3) * seg
        a0 = (p0[0] + ux * s - nx * w * 0.55, p0[1] + uy * s - ny * w * 0.55)
        a1 = (p0[0] + ux * (s + seg * 0.62) + nx * w * 0.55,
              p0[1] + uy * (s + seg * 0.62) + ny * w * 0.55)
        thick_line(surf, a0, a1, w * 0.42, base if i % 2 == 0 else scale_col(base, 0.72))


def _env_tone(freq, dur, vol=0.4, shape="sine", f_end=None, attack=0.004,
              power=1.6, noise=0.0, vib=0.0):
    n = max(1, int(dur * _SR))
    out = [0.0] * n
    phase = 0.0
    two_pi = math.pi * 2
    att_n = max(1, int(attack * _SR))
    for i in range(n):
        t = i / n
        f = freq if f_end is None else freq + (f_end - freq) * t
        if vib:
            f *= 1 + vib * math.sin(i / _SR * 30)
        phase += f / _SR
        p = phase - int(phase)
        if shape == "sine":
            s = math.sin(two_pi * phase)
        elif shape == "square":
            s = 1.0 if p < 0.5 else -1.0
        elif shape == "saw":
            s = 2 * p - 1
        elif shape == "tri":
            s = 4 * abs(p - 0.5) - 1
        else:
            s = random.uniform(-1, 1)
        if noise:
            s = s * (1 - noise) + random.uniform(-1, 1) * noise
        a = i / att_n if i < att_n else 1.0
        out[i] = s * a * ((1 - t) ** power) * vol
    return out


def _mix(parts, total=None):
    if total is None:
        total = max(int(off * _SR) + len(s) for s, off in parts)
    out = [0.0] * total
    for s, off in parts:
        o = int(off * _SR)
        for i, v in enumerate(s):
            j = o + i
            if j >= total:
                break
            out[j] += v
    return out


def _to_bytes(samples, channels=1):
    arr = array('h')
    for v in samples:
        iv = int(clamp(v, -1.0, 1.0) * 30000)
        arr.append(iv)
        if channels == 2:
            arr.append(iv)
    return arr.tobytes()


def _arp(notes, step, dur, vol, shape="tri"):
    return [(_env_tone(f, dur, vol, shape), i * step) for i, f in enumerate(notes)]


