# CEHENNEM PATRONLARI
# ---------------------------------------------------------------------
# Davranışları arena patronlarıyla aynı (dengesi oturmuş), kimlikleri başka:
# yeni ad, yeni renk ve cehennem görselliği.
HELL_BOSS_NAMES = {
    "warlord":  "CEHENNEM LORDU",
    "witch":    "KÜL CADISI",
    "colossus": "LAV KOLOSU",
    "reaper":   "RUH TOPLAYICI",
    "hive":     "AZAP ANASI",
    "dragon":   "KOR EJDERHA",
}
HELL_BOSS_COLORS = {
    "warlord":  (236, 74, 44),
    "witch":    (196, 60, 190),
    "colossus": (168, 78, 46),
    "reaper":   (226, 120, 40),
    "hive":     (246, 158, 48),
    "dragon":   (228, 58, 30),
}
# CEHENNEM'in ilk patronu EJDERHA: girer girmez oyuncuyu karşılayan,
# alev püskürten uçan dev. Sonra sırayla diğerleri gelir.
HELL_BOSS_ORDER = ["dragon", "warlord", "colossus", "reaper", "hive", "witch"]
HELL_BOSS_FIRST_WAVE = 5       # cehennemde patron: 5, 10, 15 ...
HELL_BOSS_STEP = 5
# Cehennem patronu, arenanın son patronundan (25. dalga = 4. patron) daha
# güçsüz olmasın diye güç dizini buradan başlar.
HELL_BOSS_INDEX_BASE = 4


def hell_boss_index(wave):
    return HELL_BOSS_INDEX_BASE + max(0, (int(wave) - HELL_BOSS_FIRST_WAVE) // HELL_BOSS_STEP)


class HellPortal:
    """25. dalga patronundan sonra açılan MOR portal.

    Oyuncu ölene ya da içine girene kadar haritada durur; yaklaşınca
    "E" tuşuyla girilir.
    """

    def __init__(self, x, y):
        self.x, self.y = x, y
        self.r = 46
        self.t = 0.0
        self.motes = []
        for _ in range(26):
            self.motes.append([random.uniform(0, math.tau), random.uniform(0.35, 1.25),
                               random.uniform(0.5, 1.6), random.uniform(1.5, 3.4)])

    def update(self, dt):
        self.t += dt
        for mo in self.motes:
            mo[0] += dt * mo[2] * 1.4
            mo[1] -= dt * 0.22
            if mo[1] < 0.18:
                mo[1] = 1.25
                mo[0] = random.uniform(0, math.tau)

    def in_range(self, player):
        return dist(self.x, self.y, player.x, player.y) < self.r + 70

    def draw(self, surf, t):
        pulse = 0.5 + 0.5 * math.sin(self.t * 2.4)
        # dış hale
        add_glow(surf, self.x, self.y, self.r * 4.2, HELL_PORTAL_COLOR, 0.30 + 0.16 * pulse)
        add_glow(surf, self.x, self.y, self.r * 2.0, HELL_PORTAL_COLOR2, 0.26 + 0.12 * pulse)
        # girdap: içe doğru daralan dönen halkalar
        for i in range(7):
            k = i / 6.0
            rr = self.r * (1.06 - k * 0.82)
            ang = self.t * (1.1 + i * 0.35) * (1 if i % 2 == 0 else -1)
            rect = pygame.Rect(0, 0, int(rr * 2), int(rr * 2))
            rect.center = (int(self.x), int(self.y))
            col = mix_col(HELL_PORTAL_COLOR, HELL_PORTAL_COLOR2, k)
            pygame.draw.arc(surf, col, rect, ang, ang + math.pi * 1.35, max(2, int(4 - k * 2)))
        # merkez
        pygame.draw.circle(surf, (26, 10, 42), (int(self.x), int(self.y)), int(self.r * 0.34))
        pygame.draw.circle(surf, HELL_PORTAL_COLOR2, (int(self.x), int(self.y)),
                           int(self.r * 0.34), 2)
        # içe çekilen parçacıklar
        for (a, d, spd, sz) in self.motes:
            px = self.x + math.cos(a) * self.r * d
            py = self.y + math.sin(a) * self.r * d * 0.92
            blit_disc(surf, px, py, sz, HELL_PORTAL_COLOR2, int(120 + 120 * (1.25 - d)))
        # taban halkası
        rect = pygame.Rect(0, 0, int(self.r * 2.2), int(self.r * 2.2))
        rect.center = (int(self.x), int(self.y))
        pygame.draw.ellipse(surf, (*HELL_PORTAL_COLOR, 255), rect, 3)

        # etiket
        draw_text(surf, L("ui.hell_gate"), (self.x, self.y - self.r - 42), 16,
                  HELL_PORTAL_COLOR2, bold=True, center=True)
        lab = pygame.Rect(0, 0, 150, 26)
        lab.center = (int(self.x), int(self.y + self.r + 26))
        ls = pygame.Surface(lab.size, pygame.SRCALPHA)
        pygame.draw.rect(ls, (30, 12, 48, 235), ls.get_rect(), border_radius=13)
        pygame.draw.rect(ls, (*HELL_PORTAL_COLOR, 255), ls.get_rect(), width=2, border_radius=13)
        surf.blit(ls, lab.topleft)
        draw_text(surf, L("ui.press_e"), lab.center, 13, (245, 225, 255), bold=True,
                  center=True, shadow=False)


# =====================================================================
# TUZAK / BÖLGE HASARI (yerde kırmızı uyarı, sonra patlar)
# =====================================================================

class Hazard:
    # Tuzağın rengi, onu kuran patronun imza özelliğinden gelir: ateşli
    # patronun bıraktığı havuz turuncu (alev), zehirli patronunki yeşil
    # görünsün — hepsi aynı kırmızı daire olmasın.
    TRAIT_COLORS = {
        "burn": (255, 132, 46), "inferno": (255, 116, 34),
        "venom": (150, 226, 74), "chill": (120, 196, 255),
        "vanish": (196, 116, 246), "blink": (110, 236, 208),
    }
    DEFAULT_COLOR = (255, 70, 60)

    def __init__(self, x, y, r, delay, dmg, owner=None, color=None):
        self.x, self.y = x, y
        self.r = r
        self.delay = delay
        self.dmg = dmg
        # Tuzağı kuran (patron): isabet edince can çalabilmesi için.
        self.owner = owner
        if color is None:
            trait = getattr(owner, "trait", None)
            color = self.TRAIT_COLORS.get(trait["kind"], self.DEFAULT_COLOR) if trait \
                else self.DEFAULT_COLOR
        self.color = color
        self.t = 0.0
        self.exploded = False
        self.linger = 0.0
        self.alive = True

    def update(self, dt, run):
        if not self.exploded:
            self.t += dt
            if self.t >= self.delay:
                self.exploded = True
                self.linger = 0.3
                p = run.player
                if p.alive and dist(self.x, self.y, p.x, p.y) < self.r + p.radius - 2:
                    if self.owner is not None and hasattr(self.owner, "hit_player"):
                        # Patron tuzağı: hasarla birlikte patronun imza etkisini
                        # de taşır (yakar / zehirler / yavaşlatır).
                        self.owner.hit_player(p, self.dmg, run.fx, self.x, self.y)
                    else:
                        p.take_damage(self.dmg, run.fx, self.x, self.y, "Tuzak")
                run.fx.shockwave(self.x, self.y, self.r * 1.15, self.color, 0.4, 6)
                run.fx.burst(self.x, self.y, lighten(self.color, 0.25), n=18, speed=200,
                             life=0.5, r=3.5)
                run.fx.shake(6, 0.2)
                sfx("explosion", 0.55, 0.05)
        else:
            self.linger -= dt
            if self.linger <= 0:
                self.alive = False

    def draw(self, surf, t):
        x, y = int(self.x), int(self.y)
        c = self.color
        if not self.exploded:
            frac = clamp(self.t / self.delay, 0, 1)
            blit_disc(surf, x, y, self.r * frac, c, 70)
            pulse = 0.6 + 0.4 * math.sin(t * 16)
            pygame.draw.circle(surf, scale_col(c, pulse), (x, y), int(self.r), 2)
            mark = lighten(c, 0.35)
            pygame.draw.line(surf, mark, (x - 7, y - 7), (x + 7, y + 7), 2)
            pygame.draw.line(surf, mark, (x - 7, y + 7), (x + 7, y - 7), 2)
        else:
            add_glow(surf, x, y, self.r * 1.4, lighten(c, 0.2), clamp(self.linger / 0.3, 0, 1))


# =====================================================================
# MIKNATIS  (çok nadir düşen efsanevi eşya)
# ---------------------------------------------------------------------
# Öldürülen her yaratıktan düşme şansı BİNDE İKİ BUÇUK'tur; yani ortalama
# 400 öldürmede bir görürsün. Sırf şansa bırakılmadı: belli bir öldürme
# sayısından sonra düşmemişse şans kademeli olarak yükselir ve bir noktada
# kesin düşer (aşağıdaki MAGNET_PITY_* sabitleri). Böylece kötü şans yüzünden
# hiç görmeyen oyuncu olmaz, ama eşya da bolluğa düşmez.
#
# ETKİSİ: alındığı anda HARİTADAKİ BÜTÜN altın ve tecrübe taşları —
# mesafeleri ne olursa olsun — oyuncuya uçar.
# =====================================================================

# v3.11: binde bir çok seyrekti — uzun bir koşuda bile mıknatıs bir kez ya da
# hiç görünmüyordu. Şans 2.5 katına çıktı (ortalama ~1/400 öldürme) ve
# garanti eğrisi de aynı oranda öne alındı.
MAGNET_DROP_CHANCE = 0.0025     # öldürme başına temel düşme şansı
# Garanti eğrisi SADECE aşırı kötü şansı kurtarır: temel şansın ortalamasının
# (~400 öldürme) belirgin üstünde başlar, böylece koşuların çoğunda hiç
# devreye girmez ve eşyanın nadirliği şansla belirlenmeye devam eder.
MAGNET_PITY_FROM = 1000         # bu öldürmeden sonra şans yükselmeye başlar
MAGNET_PITY_TO = 1700           # bu öldürmede kesin düşer
MAGNET_COLOR = (255, 84, 96)
MAGNET_COLOR2 = (232, 240, 255)


def magnet_drop_chance(kills_since):
    """Son mıknatıstan bu yana yapılan öldürme sayısına göre düşme şansı."""
    if kills_since >= MAGNET_PITY_TO:
        return 1.0
    if kills_since <= MAGNET_PITY_FROM:
        return MAGNET_DROP_CHANCE
    # MAGNET_PITY_FROM ile MAGNET_PITY_TO arasında doğrusal olarak 1'e çıkar.
    k = (kills_since - MAGNET_PITY_FROM) / float(MAGNET_PITY_TO - MAGNET_PITY_FROM)
    return MAGNET_DROP_CHANCE + (1.0 - MAGNET_DROP_CHANCE) * k


class MagnetDrop:
    """Yerde parıldayan, küçük haritada da görünen mıknatıs.

    Asla kaybolmaz: bu kadar nadir bir eşyanın süresi dolup yok olması
    oyuncuyu haksız yere cezalandırırdı.
    """

    def __init__(self, x, y):
        self.x = clamp(x, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
        self.y = clamp(y, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
        self.t = random.uniform(0, math.tau)
        self.collected = False
        self.alive = True

    def update(self, dt, player):
        self.t += dt
        if not player.alive:
            return
        # Toplama menzili cömerttir: nadir eşya kıl payı kaçmasın.
        pr = max(46.0, player.eff_pickup() * 1.3)
        d = dist(self.x, self.y, player.x, player.y)
        if d < pr:
            pull = clamp(1 - d / pr, 0, 1) ** 0.5
            dx, dy = norm_dir(self.x, self.y, player.x, player.y)
            spd = lerp(120, 900, pull)
            self.x += dx * spd * dt
            self.y += dy * spd * dt
        if d < 26:
            self.collected = True
            self.alive = False

    def draw(self, surf, t):
        # Yüzlerce öldürmede bir düşen bir eşya kaçırılmamalı: normal bir eşyadan
        # belirgin şekilde BÜYÜK çizilir, üstünden ışık sütunu yükselir ve
        # çevresinde içe kapanan çekim halkaları döner.
        bob = math.sin(self.t * 3.0) * 4.5
        x, y = self.x, self.y + bob
        pulse = 0.5 + 0.5 * math.sin(self.t * 5.0)
        K = 1.45                       # eşyanın boy çarpanı
        # 1) yukarı yükselen ışık sütunu — uzaktan bile göze çarpsın.
        # Kalın düz çizgi yerine yukarı doğru sönen parlama noktaları: donuk
        # renkle çizilen kalın çizgi koyu zeminde kırmızı bir levha gibi
        # duruyordu, toplamalı parlama ise gerçekten ışık gibi görünüyor.
        for i in range(7):
            f = i / 6.0
            add_glow(surf, x, y - 18 - f * 110, (20 - f * 13) * K,
                     MAGNET_COLOR2 if i < 2 else MAGNET_COLOR,
                     (0.30 - 0.26 * f) * (0.7 + 0.3 * pulse))
        # 2) parıltı: iki kat hâle + dönen ışık kolları
        add_glow(surf, x, y, (54 + pulse * 18) * K, MAGNET_COLOR, 0.38 + 0.30 * pulse)
        add_glow(surf, x, y, 26 * K, MAGNET_COLOR2, 0.18 + 0.18 * pulse)
        for i in range(6):
            a = self.t * 2.2 + i * math.tau / 6
            r0, r1 = 18 * K, (34 + pulse * 9) * K
            pygame.draw.line(surf, scale_col(MAGNET_COLOR2, 0.45 + pulse * 0.55),
                             (x + math.cos(a) * r0, y + math.sin(a) * r0),
                             (x + math.cos(a) * r1, y + math.sin(a) * r1), 2)
        # 3) İÇE kapanan çekim halkaları — "her şeyi çeker" hissi
        for i in range(3):
            ph = (self.t * 0.8 + i / 3.0) % 1.0
            rr = int(lerp(62 * K, 12, ph))
            dim = 0.55 * (1 - abs(ph - 0.5) * 2) + 0.12
            if rr > 3 and dim > 0.06:
                pygame.draw.circle(surf, scale_col(MAGNET_COLOR, dim),
                                   (int(x), int(y)), rr, 2)
        # 4) at nalı mıknatıs: kalın kırmızı kemer + iki çelik kutup.
        # Kutuplar kemerin UÇLARINDAN başlar: konumları göz kararı verilmiyor,
        # yayın bitiş açısından hesaplanıyor — yoksa kemerle kutuplar arasında
        # boşluk kalıyor ve eşya parçalanmış görünüyordu.
        A0, A1 = math.pi * 0.12, math.pi * 0.88     # yayın başlangıç/bitiş açısı
        rad = 25 * K                                # yayın orta yarıçapı
        band = 8 * K                                # kemerin kalınlığı
        cy = y + 3 * K
        rect = pygame.Rect(0, 0, int(rad * 2), int(rad * 2))
        rect.center = (int(x), int(cy))
        pygame.draw.arc(surf, OUTLINE, rect.inflate(6, 6), A0, A1, int(band + 4))
        pygame.draw.arc(surf, MAGNET_COLOR, rect, A0, A1, int(band))
        pygame.draw.arc(surf, lighten(MAGNET_COLOR, 0.35),
                        rect.inflate(int(-band * 0.8), int(-band * 0.8)),
                        A0 + 0.07, A1 - 0.07, max(2, int(band * 0.32)))
        # Yayın uçları. pygame'in arc'ı bandı dikdörtgenin KENARINDAN İÇERİ
        # doğru çizer; yani dış yarıçap rad, bandın ORTASI rad - band/2'dir.
        # Bacaklar bu orta yarıçaptan çıkmazsa kemerin dışına taşıyor ve
        # at nalı kopuk görünüyordu.
        mid = rad - band / 2.0
        ex = mid * math.cos(A0)
        ey = -mid * math.sin(A0)
        leg_len = 16 * K
        for sgn in (-1, 1):
            px = x + sgn * ex
            y0 = cy + ey
            pygame.draw.line(surf, OUTLINE, (px, y0 - 2), (px, y0 + leg_len), int(band + 4))
            pygame.draw.line(surf, MAGNET_COLOR2, (px, y0), (px, y0 + leg_len), int(band))
            pygame.draw.circle(surf, WHITE, (int(px - band * 0.22), int(y0 + leg_len * 0.4)),
                               max(1, int(band * 0.22)))


# =====================================================================
# ZEMZEM SUYU  —  yerde kalan su birikintisi
# ---------------------------------------------------------------------
# Silah suyu fırlatır, su düştüğü yerde bir süre KALIR. İçine giren düşman
# hem yavaşlar hem de saniye saniye hasar alır.
# =====================================================================

ZEMZEM_COLOR = (96, 198, 255)
ZEMZEM_COLOR2 = (208, 246, 255)


# =====================================================================
# SEVİYE TAŞI  (v3.23) — mor, anında bir seviye verir
# ---------------------------------------------------------------------
# MIKNATIS'la AYNI şansla düşer (aynı eğri, ayrı sayaç): yani ikisi
# birbirinin şansını yemez, ama aynı nadirlikte kalırlar. Toplandığı anda
# otomatik olarak BİR SEVİYE verir — kart ekranı normal seviye atlamada
# olduğu gibi açılır.
LEVEL_COLOR = (178, 110, 255)
LEVEL_COLOR2 = (236, 214, 255)


class LevelDrop:
    """Yerde duran mor SEVİYE TAŞI. Toplanınca anında bir seviye verir.

    MagnetDrop ile aynı toplama davranışı (cömert menzil, asla kaybolmaz);
    yalnızca görünüşü ve etkisi başka.
    """

    def __init__(self, x, y):
        self.x = clamp(x, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
        self.y = clamp(y, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
        self.t = random.uniform(0, math.tau)
        self.collected = False
        self.alive = True

    def update(self, dt, player):
        self.t += dt
        if not player.alive:
            return
        pr = max(46.0, player.eff_pickup() * 1.3)
        d = dist(self.x, self.y, player.x, player.y)
        if d < pr:
            pull = clamp(1 - d / pr, 0, 1) ** 0.5
            dx, dy = norm_dir(self.x, self.y, player.x, player.y)
            spd = lerp(120, 900, pull)
            self.x += dx * spd * dt
            self.y += dy * spd * dt
        if d < 26:
            self.collected = True
            self.alive = False

    def draw(self, surf, t):
        """Yukarı uzanan ışık sütunlu mor kristal."""
        bob = math.sin(self.t * 3.0) * 4.5
        x, y = self.x, self.y + bob
        pulse = 0.5 + 0.5 * math.sin(self.t * 5.0)
        # ışık sütunu
        for i in range(7):
            k = i / 6.0
            py = y - 16 - k * 46
            rr = max(1, int(5 * (1 - k) + 1))
            a = int(140 * (1 - k) * (0.55 + 0.45 * pulse))
            blit_disc(surf, x, py, rr, LEVEL_COLOR2 if i < 2 else LEVEL_COLOR, a)
        add_glow(surf, x, y, 54 + pulse * 18, LEVEL_COLOR, 0.38 + 0.30 * pulse)
        add_glow(surf, x, y, 26, LEVEL_COLOR2, 0.18 + 0.18 * pulse)
        # dönen üç kıvılcım
        for i in range(3):
            a = self.t * 2.2 + i * math.tau / 3
            px, py = x + math.cos(a) * 26, y + math.sin(a) * 26 * 0.6
            pygame.draw.circle(surf, LEVEL_COLOR2, (int(px), int(py)), 3)
        # kristal gövde (sivri altıgen)
        R = 15.0
        pts = [(x, y - R * 1.5), (x + R * 0.8, y - R * 0.3),
               (x + R * 0.55, y + R * 1.1), (x - R * 0.55, y + R * 1.1),
               (x - R * 0.8, y - R * 0.3)]
        pygame.draw.polygon(surf, OUTLINE, [(px, py + 2) for px, py in pts])
        pygame.draw.polygon(surf, LEVEL_COLOR, pts)
        pygame.draw.polygon(surf, lighten(LEVEL_COLOR, 0.45), pts, 2)
        # iç parıltı
        pygame.draw.polygon(surf, lighten(LEVEL_COLOR, 0.65),
                            [(x, y - R * 1.1), (x + R * 0.3, y - R * 0.1),
                             (x, y + R * 0.5), (x - R * 0.3, y - R * 0.1)])


class WaterZone:
    """Zemzem birikintisi: yavaşlatır ve saniyede hasar verir."""

    def __init__(self, x, y, r, dps, life, slow=0.52, lvl=1):
        self.x = clamp(x, ARENA_RECT.left + 20, ARENA_RECT.right - 20)
        self.y = clamp(y, ARENA_RECT.top + 20, ARENA_RECT.bottom - 20)
        self.r = r
        self.dps = dps
        self.lvl = max(1, int(lvl))   # tek-atma freni için silahın seviyesi
        self.life = life
        self.max_life = life
        self.slow = slow
        self.tick = 0.0
        self.t = 0.0
        self.alive = True
        # Su birikintisinin düzensiz kıyı çizgisi — her birikinti farklı görünsün.
        self.shape = [random.uniform(0.82, 1.0) for _ in range(14)]
        self.splash = 0.28          # yere çarpma anının süresi

    def update(self, dt, run):
        self.t += dt
        self.life -= dt
        self.splash = max(0.0, self.splash - dt)
        if self.life <= 0:
            self.alive = False
            return
        # Büyümesi: ilk 0.18 saniyede yayılır, sonunda buharlaşırken küçülür.
        self.tick -= dt
        if self.tick > 0:
            return
        self.tick = 0.18
        rad = self.cur_r()
        splash_left = 3          # bu tikte atılabilecek kıvılcım sayısı
        for e in run._all_targets():
            if not e.alive:
                continue
            if dist(self.x, self.y, e.x, e.y) <= rad + getattr(e, "radius", 12) * 0.6:
                run._field_damage(e, self.dps * 0.18, wlvl=self.lvl)
                if hasattr(e, "apply_slow"):
                    e.apply_slow(self.slow, 0.55)
                # PARÇACIK BÜTÇESİ: eskiden her düşman için kıvılcım atıyordu.
                # Kalabalıkta bu, 650'lik parçacık tavanını tek başına
                # doldurup kare süresini iki katına çıkarıyordu. Artık tik
                # başına en fazla 3 kıvılcım çıkıyor.
                if splash_left > 0 and random.random() < 0.5:
                    splash_left -= 1
                    run.fx.spark(e.x + random.uniform(-8, 8), e.y + random.uniform(-6, 6),
                                 ZEMZEM_COLOR2, random.uniform(-20, 20), random.uniform(-70, -30),
                                 0.35, 2.0)

    def cur_r(self):
        grow = clamp(self.t / 0.18, 0, 1)
        fade = clamp(self.life / 0.5, 0.55, 1.0)
        return self.r * grow * fade

    def draw(self, surf, t):
        rad = self.cur_r()
        if rad < 3:
            return
        x, y = self.x, self.y
        n = len(self.shape)
        # ÇİZİM NOTU: burada bilerek geçici SRCALPHA yüzeyi AYIRMIYORUZ.
        # 8. seviyede birikinti yarıçapı ~240 px oluyor; her karede üç tane
        # 500x500 yüzey ayırmak tek başına kare süresini birkaç milisaniye
        # şişiriyordu. Saydam gövde için önbellekli blit_disc kullanılıyor,
        # kalan çizgiler doğrudan hedefe (donuk renkle) çiziliyor.
        # 1) su gövdesi — önbellekli saydam disk
        blit_disc(surf, x, y, rad * 0.94, ZEMZEM_COLOR, 92)
        add_glow(surf, x, y, rad * 0.9, ZEMZEM_COLOR, 0.20)
        # 2) düzensiz, dalgalanan kıyı çizgisi
        pts = []
        for i in range(n):
            a = i * math.tau / n
            wob = 1.0 + 0.055 * math.sin(t * 2.6 + i * 1.7)
            rr = rad * self.shape[i] * wob
            pts.append((x + math.cos(a) * rr, y + math.sin(a) * rr * 0.86))
        pygame.draw.polygon(surf, ZEMZEM_COLOR2, pts, 2)
        # 3) yüzeyde dışa açılan ışık halkaları
        for i in range(3):
            ph = (t * 0.55 + i / 3.0) % 1.0
            rr = rad * (0.25 + 0.72 * ph)
            if rr < 4:
                continue
            col = scale_col(ZEMZEM_COLOR2, 0.30 + 0.55 * (1 - ph))
            pygame.draw.ellipse(surf, col,
                                (int(x - rr), int(y - rr * 0.86), int(rr * 2), int(rr * 2 * 0.86)), 2)
        # 4) yere çarpma anı: yukarı sıçrayan damlalar
        if self.splash > 0:
            k = self.splash / 0.28
            for i in range(8):
                a = i * math.tau / 8 + self.t
                rr = rad * (1.0 - k * 0.5)
                pygame.draw.circle(surf, ZEMZEM_COLOR2,
                                   (int(x + math.cos(a) * rr), int(y + math.sin(a) * rr * 0.86 - 16 * k)),
                                   max(1, int(3 * k)))


# =====================================================================
# BARAN'IN PAPUCU  —  ayak izinde kalan ateş halkası
# ---------------------------------------------------------------------
# Oyuncu her adım attığında arkasında bir ateş HALKASI bırakır. Halka
# ömrü boyunca KENDİ İÇİNE doğru kapanarak söner; içinde kalan düşman yanar.
# Bu eşya bir kez alındıktan sonra asla bitmez — sürekli çalışır.
# =====================================================================

SHOE_COLOR = (255, 142, 52)
SHOE_COLOR2 = (255, 226, 140)
# BUZ İZİ: aynı mekanik, başka element. Yakmak yerine DONDURUR.
FROST_COLOR = (124, 208, 255)
FROST_COLOR2 = (226, 246, 255)


class FireRing:
    """Ayak izinde bırakılan, içine doğru kapanan halka.

    İki modu var:
      ice=False : BARAN'IN PAPUCU — ateş halkası, içindekini yakar.
      ice=True  : BUZ İZİ — don halkası, içindekini yavaşlatır.
    İkisi aynı sınıfı paylaşıyor çünkü mekanik birebir aynı; yalnızca renk,
    biçim ve uygulanan etki değişiyor.
    """

    def __init__(self, x, y, r, dps, life, burn=0.0, ice=False, slow=0.55, lvl=1):
        self.x, self.y = x, y
        self.r0 = r
        self.dps = dps
        self.lvl = max(1, int(lvl))   # tek-atma freni için silahın seviyesi
        self.life = life
        self.max_life = max(0.05, life)
        self.burn = burn
        self.ice = ice
        self.slow = slow
        self.tick = 0.0
        self.t = 0.0
        self.alive = True
        self.seed = random.uniform(0, math.tau)
        # BUZ halkasının kırılgan kenarı: her halkanın kendi kristal deseni
        self.spikes = [random.uniform(0.86, 1.14) for _ in range(12)] if ice else None

    def cur_r(self):
        """Halkanın o anki yarıçapı — ömrü boyunca içine doğru kapanır."""
        k = clamp(self.life / self.max_life, 0.0, 1.0)
        # Başta hızlı açılır (0.12 sn), sonra yavaşça merkeze çöker.
        opening = clamp(self.t / 0.12, 0, 1)
        return self.r0 * opening * (0.12 + 0.88 * k)

    def update(self, dt, run):
        self.t += dt
        self.life -= dt
        if self.life <= 0:
            self.alive = False
            return
        self.tick -= dt
        if self.tick > 0:
            return
        self.tick = 0.16
        rad = self.cur_r()
        for e in run._all_targets():
            if not e.alive:
                continue
            if dist(self.x, self.y, e.x, e.y) <= rad + getattr(e, "radius", 12) * 0.5:
                run._field_damage(e, self.dps * 0.16, wlvl=self.lvl)
                if self.ice:
                    if hasattr(e, "apply_slow"):
                        e.apply_slow(self.slow, 0.8)
                elif self.burn > 0 and hasattr(e, "apply_burn"):
                    e.apply_burn(self.burn, 1.4)

    def draw(self, surf, t):
        rad = self.cur_r()
        if rad < 2:
            return
        x, y = self.x, self.y
        k = clamp(self.life / self.max_life, 0.0, 1.0)
        # Geçici yüzey ayırmadan çizim: aynı anda 15-20 halka yaşayabiliyor,
        # her biri için yüzey ayırmak kare süresini uçuruyordu. Saydam gövde
        # için önbellekli blit_disc, kenarlar için doğrudan çizim.
        if self.ice:
            # ---- BUZ HALKASI: keskin kristal kenar, içeride donmuş zemin ----
            blit_disc(surf, x, y, rad * 0.96, FROST_COLOR, int(52 * k))
            add_glow(surf, x, y, rad * 1.10, FROST_COLOR, 0.16 + 0.18 * k)
            n = len(self.spikes)
            pts, pts_in = [], []
            for i in range(n):
                a = i * math.tau / n
                sp = self.spikes[i]
                pts.append((x + math.cos(a) * rad * sp, y + math.sin(a) * rad * sp))
                pts_in.append((x + math.cos(a) * rad * 0.62, y + math.sin(a) * rad * 0.62))
            pygame.draw.polygon(surf, scale_col(FROST_COLOR2, 0.40 + 0.55 * k), pts, 3)
            pygame.draw.polygon(surf, scale_col(FROST_COLOR, 0.34 + 0.44 * k), pts_in, 2)
            # merkezden dışa uzanan don çatlakları
            for i in range(0, n, 2):
                a = i * math.tau / n + self.seed * 0.1
                pygame.draw.line(surf, scale_col(FROST_COLOR2, 0.30 + 0.40 * k),
                                 (x + math.cos(a) * rad * 0.22, y + math.sin(a) * rad * 0.22),
                                 (x + math.cos(a) * rad * 0.92, y + math.sin(a) * rad * 0.92), 2)
            # havada asılı kalan kar taneleri
            if random.random() < 0.4:
                a = random.uniform(0, math.tau)
                rr = rad * random.uniform(0.3, 1.0)
                draw_icon(surf, x + math.cos(a) * rr, y + math.sin(a) * rr,
                          "snow", FROST_COLOR2, max(2, int(3 * k)))
            return
        blit_disc(surf, x, y, rad * 0.96, SHOE_COLOR, int(46 * k))
        add_glow(surf, x, y, rad * 1.15, SHOE_COLOR, 0.22 + 0.22 * k)
        # alev dili çemberi: yarıçapı titreyen iki çokgen
        pts, pts_in = [], []
        n = 22
        for i in range(n):
            a = i * math.tau / n
            fl = 1.0 + 0.16 * math.sin(t * 11 + self.seed + i * 2.1)
            pts.append((x + math.cos(a) * rad * fl, y + math.sin(a) * rad * fl))
            pts_in.append((x + math.cos(a) * rad * 0.72, y + math.sin(a) * rad * 0.72))
        pygame.draw.polygon(surf, scale_col(SHOE_COLOR, 0.45 + 0.55 * k), pts, 4)
        pygame.draw.polygon(surf, scale_col(SHOE_COLOR2, 0.35 + 0.55 * k), pts_in, 2)
        # halkanın üstünde yukarı süzülen kıvılcım
        if random.random() < 0.5:
            a = random.uniform(0, math.tau)
            pygame.draw.circle(surf, SHOE_COLOR2,
                               (int(x + math.cos(a) * rad), int(y + math.sin(a) * rad)),
                               random.randint(1, 2))


# =====================================================================
# HORTUM  —  düşmanları ortaya toplayan kasırga
# ---------------------------------------------------------------------
# 15 saniyede bir düşer: menzilindeki bütün yaratıkları merkezine çeker ve
# her birinin canını BİR KEZ azaltır (patronlar hariç: patronun canı
# azalmaz, sadece savrulur). v3.10'dan beri SEVİYE ATLAR: menzil seviyeyle
# birlikte büyür.
#
# v3.11 — SEVİYE ARTIK HASAR DEMEK: hortum eskiden her seviyede yalnızca
# biraz genişliyordu, vurduğu iş aynı kalıyordu. Artık iki koldan güçleniyor:
#   1) can yarılaması derinleşiyor (TORNADO_HP_CUT_STEPS),
#   2) huninin içinde kalan yaratık SÜREKLİ hasar alıyor (dmg/dpl alanları).
# İlk iki seviye bilerek eski dengede bırakıldı.
# =====================================================================

TORNADO_COLOR = (186, 218, 240)
TORNADO_COLOR2 = (240, 250, 255)
# Canın KALAN oranı (0.65 = canı %35 azalır). Tavan 5'ten 25'e çıkınca
# kesme payı da 25 seviyeye yayıldı: ilk iki seviye yine eski değerde
# (0.65), sonra her seviye biraz daha derin kesiyor, 25'te 0.24'e iniyor.
TORNADO_HP_CUT_BASE = 0.84      # v3.17: 1-2. seviyede canın kalan oranı (%16 keser)
TORNADO_HP_CUT_PER_LEVEL = 0.010
TORNADO_HP_CUT_MIN = 0.55       # v3.14: hiçbir seviyede canın %45'inden fazlasını kesmez


def tornado_hp_cut(lvl):
    """HORTUM'un yaratığı içine çekerken canından kestiği pay.

    Dönen değer, canın KALAN oranıdır (0.65 = canı %35 azalır). İlk iki
    seviye bilerek eski değerde bırakıldı ("ilk 2 seviye gayet iyi"); 3.
    seviyeden sonra her seviye canı biraz daha derinden kesiyor.
    """
    over = max(0.0, weapon_growth(lvl) - 1.0)
    return max(TORNADO_HP_CUT_MIN,
               TORNADO_HP_CUT_BASE - TORNADO_HP_CUT_PER_LEVEL * over)


class Tornado:
    """Menzilindeki yaratıkları merkezine çeken, içindekini öğüten kasırga."""

    # NERF (v3.10): 520 px hâlâ ekranın büyük bölümünü kapsıyordu ("ekranımın
    # yarısı kadar bile olabilir" isteği üstüne). Menzil artık 1. seviyede
    # ekranın YAKLAŞIK YARISI kadar (~260 px) ve her seviyede biraz açılıyor;
    # en yüksek seviyede bile eski değerin çok altında kalıyor.
    BASE_PULL_R = 200.0        # v3.14: 1. seviyedeki çekim menzili
    PULL_R_PER_LEVEL = 4.0     # v3.14: her seviyede eklenen menzil (25. sv: ~296 px)
    LIFE = 2.6                 # v3.22: kasırganın ömrü (saniye)
    GRIND_TICK = 0.20          # öğütme hasarının tik aralığı (saniye)
    # Geriye dönük uyumluluk: bu sınıfa hâlâ Tornado.PULL_R diye erişen bir
    # yer kalırsa (mod/araç), 1. seviye değeriyle eşleşsin.
    PULL_R = BASE_PULL_R

    def __init__(self, x, y, lvl=1, hp_cut=None, dps=0.0):
        self.x = clamp(x, ARENA_RECT.left + 80, ARENA_RECT.right - 80)
        self.y = clamp(y, ARENA_RECT.top + 80, ARENA_RECT.bottom - 80)
        self.lvl = max(1, lvl)
        # NERF (v3.10): menzil artık seviyeyle büyüyen KİŞİSEL bir değer.
        self.PULL_R = self.BASE_PULL_R + self.PULL_R_PER_LEVEL * weapon_growth(self.lvl)
        self.life = self.LIFE
        self.t = 0.0
        self.alive = True
        # Can yarılaması artık SEVİYEYE bağlı (bkz. tornado_hp_cut). Çağıran
        # açıkça bir değer verirse (eski çağrılar / mod) o değer geçerlidir.
        self.hp_cut = tornado_hp_cut(self.lvl) if hp_cut is None else hp_cut
        # ÖĞÜTME: hortum artık boş bir savurma değil; içinde kalan her saniye
        # hasar alır. Değer seviyeyle büyür (bkz. HORTUM satırındaki dmg/dpl).
        self.dps = max(0.0, dps)
        self.grind_t = 0.0
        # Canı zaten kesilmiş yaratıklar. Burada id() DEĞİL yaratığın KENDİSİ
        # saklanıyor: hortum 2.4 saniye yaşıyor ve bu sürede ölen bir
        # yaratığın id'si yeni doğan birine düşebiliyordu — o yeni yaratık da
        # "canı zaten kesilmiş" sayılıp kesmeden kurtuluyordu. Küme hortumla
        # birlikte yok olduğu için nesne tutmak sızıntı yapmaz.
        self.cut = set()
        self.debris = []        # çevresinde dönen enkaz: (açı, yarıçap, yükseklik, hız)
        for _ in range(26):
            self.debris.append([random.uniform(0, math.tau), random.uniform(20, 150),
                                random.uniform(0, 120), random.uniform(2.6, 5.4)])

    def update(self, dt, run):
        self.t += dt
        self.life -= dt
        if self.life <= 0:
            self.alive = False
            return
        # Öğütme hasarı tik tik uygulanır: her karede vurmak hem hasar
        # sayılarını hem de can çalma / infaz kapısını gereksiz yere yoruyor.
        # ÖLÇEK DÜZELTMESİ (v3.22): burada `self.dps` bir kez daha
        # GRIND_TICK ile çarpılıyordu, yani silah satırındaki `dmg` değeri
        # saniyelik sayılıp beşe bölünüyordu. Oyundaki diğer bütün alan
        # silahlarında (PENTAGRAM, PAPUÇ, BUZ İZİ) `dmg` TİK BAŞINA hasardır;
        # HORTUM tek başına farklı davranıyordu. Ölçüm: 20. dalgada patrona
        # 12 saniyede 6.1 DPS veriyordu — sonraki en düşük silah 45.1 (ZEMZEM),
        # en yükseği 839.6 (KALKAN). Artık tik başına uygulanıyor.
        grind = 0.0
        self.grind_t -= dt
        if self.dps > 0 and self.grind_t <= 0:
            self.grind_t = self.GRIND_TICK
            grind = self.dps
        for d in self.debris:
            d[0] += d[3] * dt
            d[2] += 46 * dt
            if d[2] > 130:
                d[2] = 0.0
                d[1] = random.uniform(40, 150)
        for e in run._all_targets():
            if not e.alive:
                continue
            d = dist(self.x, self.y, e.x, e.y)
            if d > self.PULL_R:
                continue
            boss = bool(getattr(e, "is_boss", False))
            # 1) CANI YARIYA İNDİR — yaratık başına yalnızca bir kez.
            # Canı doğrudan bölüyoruz: take_damage kullanılsa zırh araya girer
            # ve "yarı can" sözü tutulmazdı. Patronun canına dokunulmaz.
            if e not in self.cut:
                self.cut.add(e)
                if not boss and e.hp > 1:
                    # AĞIR yaratıklarda (tank/elit/zırhlı) kesme payı yarıya
                    # iner: hortum onları yumuşatır ama devirmez.
                    cut = self.hp_cut
                    if enemy_weight_class(e) == "tough":
                        cut = 1.0 - (1.0 - cut) * 0.55
                    e.hp = max(1.0, e.hp * cut)
                    e.hit_flash = 0.16
                    run.fx.popup(e.x, e.y - getattr(e, "radius", 12) - 6,
                                 f"-%{int(round((1 - cut) * 100))} CAN",
                                 TORNADO_COLOR2, 14, life=0.6)
            # 2) ÖĞÜT — huninin içinde kalan her an hasar alır. Patron da
            # bundan payını alır (canı yarılanmıyordu, hasarı yiyor).
            if grind > 0:
                if run._field_damage(e, grind, wlvl=self.lvl):
                    continue
            # 3) MERKEZE ÇEK — patron daha ağırdır, daha az savrulur.
            dx, dy = norm_dir(e.x, e.y, self.x, self.y)
            spd = (150.0 if boss else 430.0) * clamp(d / 160.0, 0.25, 1.0)
            # Çekerken hafifçe etrafında döndür: düz içeri sürüklenmesin.
            tx, ty = -dy, dx
            e.x += (dx * spd + tx * spd * 0.42) * dt
            e.y += (dy * spd + ty * spd * 0.42) * dt
            e.x = clamp(e.x, ARENA_RECT.left + 16, ARENA_RECT.right - 16)
            e.y = clamp(e.y, ARENA_RECT.top + 16, ARENA_RECT.bottom - 16)

    def draw(self, surf, t):
        x, y = self.x, self.y
        k = clamp(self.life / self.LIFE, 0, 1)
        fade = clamp(self.t / 0.25, 0, 1) * clamp(self.life / 0.4, 0, 1)
        add_glow(surf, x, y, 120, TORNADO_COLOR, 0.22 * fade)
        # Huni ve toz halkaları doğrudan hedefe çizilir; eskiden her elips için
        # ayrı bir SRCALPHA yüzeyi ayrılıyordu (kare başına 13 yüzey).
        # Saydamlık yerine rengi karartıyoruz: koyu zeminde göz aynı şeyi görür.
        for i in range(11):
            h = i / 10.0
            ey = y - h * 150
            erx = lerp(16, 118, h ** 0.8)
            ery = erx * 0.34
            wob = math.sin(t * 7 - h * 5.2) * (8 + h * 20)
            dim = (0.60 - 0.28 * h) * fade
            if dim <= 0.04:
                continue
            rect = (int(x + wob - erx), int(ey - ery), int(erx * 2), int(ery * 2))
            pygame.draw.ellipse(surf, scale_col(TORNADO_COLOR, dim), rect, 3)
            if erx > 26:
                inner = (int(x + wob - erx * 0.7), int(ey - ery * 0.7),
                         int(erx * 1.4), int(ery * 1.4))
                pygame.draw.ellipse(surf, scale_col(TORNADO_COLOR2, dim * 0.55), inner, 2)
        # çevresinde dönen enkaz
        for d in self.debris:
            a, rr, hh, _ = d
            px = x + math.cos(a) * rr * (0.35 + hh / 200.0)
            py = y - hh + math.sin(a) * rr * 0.30
            col = TORNADO_COLOR2 if (hh % 2 < 1) else TORNADO_COLOR
            pygame.draw.circle(surf, col, (int(px), int(py)), max(1, int(3 * fade)))
        # zeminde dışa açılan toz halkası
        for i in range(2):
            ph = (t * 1.4 + i * 0.5) % 1.0
            rr = lerp(30, self.PULL_R * 0.42, ph)
            dim = 0.42 * (1 - ph) * fade
            if dim > 0.04:
                pygame.draw.ellipse(surf, scale_col(TORNADO_COLOR, dim),
                                    (int(x - rr), int(y - rr * 0.35),
                                     int(rr * 2), int(rr * 0.7)), 2)
        # ömrü dolarken huni incelip tek bir çizgiye düşer
        if k < 0.3:
            pygame.draw.line(surf, TORNADO_COLOR2, (x, y - 150 * k), (x, y), 2)


# =====================================================================
# BALTA  —  hedefe gidip GERİ DÖNEN bumerang balta
# =====================================================================

AXE_COLOR = (235, 140, 74)


def draw_axe_shape(surf, x, y, spin, k=1.0, color=AXE_COLOR, glow=0.6):
    """Dönen iki ağızlı savaş baltası. k, baltanın boy çarpanıdır."""
    hx, hy = math.cos(spin), math.sin(spin)
    nx, ny = -hy, hx
    haft = 15 * k
    if glow > 0:
        add_glow(surf, x, y, 28 * k, color, glow)
    # sap
    pygame.draw.line(surf, OUTLINE, (x - hx * haft, y - hy * haft),
                     (x + hx * haft, y + hy * haft), max(3, int(7 * k)))
    pygame.draw.line(surf, (108, 72, 44), (x - hx * haft, y - hy * haft),
                     (x + hx * haft, y + hy * haft), max(2, int(5 * k)))
    # iki ağız
    for sgn in (-1, 1):
        bx, by = x + hx * 12 * k * sgn, y + hy * 12 * k * sgn
        blade = [(bx + hx * 9 * k * sgn, by + hy * 9 * k * sgn),
                 (bx + nx * 11 * k, by + ny * 11 * k),
                 (bx - hx * 6 * k * sgn, by - hy * 6 * k * sgn),
                 (bx - nx * 11 * k, by - ny * 11 * k)]
        pygame.draw.polygon(surf, OUTLINE, blade)
        pygame.draw.polygon(surf, (232, 238, 248), blade)
        pygame.draw.polygon(surf, scale_col(color, 0.9), blade, max(1, int(2 * k)))
        # ağzın ucunda kıvılcım
        pygame.draw.circle(surf, (255, 248, 230),
                           (int(x + hx * 20 * k * sgn), int(y + hy * 20 * k * sgn)),
                           max(1, int(2 * k)))


class FlyingAxe:
    """Rastgele bir düşmana uçup oyuncuya GERİ DÖNEN balta.

    İki aşaması var: "out" (hedefe gidiş) ve "back" (oyuncuya dönüş).
    Dönüşte isabet listesi sıfırlanır — yani aynı düşmana gidişte ve
    dönüşte ayrı ayrı vurur.
    """

    OUT_SPEED = 620.0
    BACK_SPEED = 760.0
    MAX_OUT = 1.5           # hedefe varamazsa bu süre sonunda geri döner

    def __init__(self, player, target, dmg, k=1.0, color=AXE_COLOR, lvl=1):
        self.x, self.y = player.x, player.y
        self.dmg = dmg
        self.lvl = max(1, int(lvl))     # tek-atma freni için silahın seviyesi
        self.k = k                      # boy çarpanı (seviyeyle büyür)
        self.color = color
        self.phase = "out"
        self.target = target
        self.tx, self.ty = target.x, target.y
        self.spin = random.uniform(0, math.tau)
        self.t = 0.0
        self.hit_set = set()
        self.alive = True
        self.trail = []                 # son konumlar: hareket bulanıklığı için

    def update(self, dt, run):
        p = run.player
        self.t += dt
        self.spin += dt * 17
        self.trail.append((self.x, self.y, self.spin))
        if len(self.trail) > 5:
            self.trail.pop(0)

        if self.phase == "out":
            # Hedef yaşıyorsa peşinden git; öldüyse son bilinen yere devam et.
            if self.target is not None and getattr(self.target, "alive", False):
                self.tx, self.ty = self.target.x, self.target.y
            dx, dy = norm_dir(self.x, self.y, self.tx, self.ty)
            self.x += dx * self.OUT_SPEED * dt
            self.y += dy * self.OUT_SPEED * dt
            if dist(self.x, self.y, self.tx, self.ty) < 26 or self.t > self.MAX_OUT:
                self.phase = "back"
                self.hit_set.clear()    # dönüşte yeniden vurabilsin
                run.fx.ring(self.x, self.y, self.color, n=10, speed=200, life=0.28, r=2.6 * self.k)
        else:
            dx, dy = norm_dir(self.x, self.y, p.x, p.y)
            self.x += dx * self.BACK_SPEED * dt
            self.y += dy * self.BACK_SPEED * dt
            if dist(self.x, self.y, p.x, p.y) < 26 or self.t > self.MAX_OUT + 3.2:
                self.alive = False
                run.fx.spark(p.x, p.y, self.color, 0, -40, 0.25, 3)
                return

        hit_r = 19 * self.k
        for e in run._all_targets():
            if not e.alive or id(e) in self.hit_set:
                continue
            if dist(self.x, self.y, e.x, e.y) < hit_r + getattr(e, "radius", 12):
                self.hit_set.add(id(e))
                run._weapon_hit(e, self.dmg, kb=180, wlvl=self.lvl)
                # 8 balta aynı anda uçarken her isabette 6 parçacık parçacık
                # tavanını dolduruyordu; isabetlerin yarısında 3 parçacık yeter.
                if random.random() < 0.5:
                    run.fx.burst(self.x, self.y, lighten(self.color, 0.3), n=3, speed=150,
                                 life=0.28, r=2.6)

    def draw(self, surf, t):
        # 1) geçmiş konumlar — sönen hayaletler
        for i, (gx, gy, gs) in enumerate(self.trail[:-1]):
            fade = (i + 1) / max(1, len(self.trail))
            draw_axe_shape(surf, gx, gy, gs, self.k * (0.6 + 0.3 * fade),
                           scale_col(self.color, 0.35 + 0.3 * fade), glow=0.0)
        # 2) süpürme halkası
        rr = int(24 * self.k)
        ring_a = int(70 + 50 * abs(math.sin(self.spin * 2)))
        rs = pygame.Surface((rr * 2 + 6, rr * 2 + 6), pygame.SRCALPHA)
        pygame.draw.circle(rs, (*self.color, ring_a), (rr + 3, rr + 3), rr, 3)
        surf.blit(rs, (self.x - rr - 3, self.y - rr - 3))
        # 3) asıl balta
        draw_axe_shape(surf, self.x, self.y, self.spin, self.k, self.color, glow=0.6)


# =====================================================================
# KIRBAÇ  —  şaklayıp düşmanı savuran darbe (yalnızca görsel)
# ---------------------------------------------------------------------
# Hasar ve savurma kırbaç atıldığı anda hesaplanır; bu nesne yalnızca
# şaklama ANINI çizer.
# =====================================================================

WHIP_COLOR = (238, 152, 84)
WHIP_COLOR2 = (255, 226, 176)


class WhipLash:
    """Kırbacın savruluşu — baktığın yöne şaklayan deri bir kamçı.

    ÇİZİM NOTU (v3.12): eski hâli, kalınlığı azalan bir sürü kısa çizginin
    uç uca eklenmesiyle çiziliyordu. Her çizginin kendi yuvarlak ucu olduğu
    için kırbaç "boncuk dizisi" gibi görünüyor, kabza da oyuncunun gövdesinin
    ortasında duruyordu. Artık kırbaç tek parça bir ŞERİT (değişken kalınlıkta
    kapalı çokgen) olarak çiziliyor:

        kontur  ->  koyu deri gövde  ->  açık deri  ->  üst kenar ışığı

    Bu dört katman üst üste gelince yüzey hacim kazanıyor ve kenarlar pürüzsüz
    çıkıyor. Üstüne şunlar bindi:
      * elde duran, deri sargılı gerçek bir KABZA,
      * ucun arkasından gelen ve sönen HAREKET İZİ (hayalet kırbaçlar),
      * tam açılırken ucundan çıkan ince KAMÇI UCU ve şaklama kıvılcımı.

    Savurma yayı bilerek hasar konisinin (WHIP_ARC) içinde kalır: görünen
    darbe, gerçekten vurulan alanla örtüşür.

    Oyuncuyu TAKİP eder — kırbaç 0.32 saniye yaşıyor ve oyuncu bu sürede
    kıpırdıyor; sabit kalsa kırbaç elinden kopmuş gibi duruyordu.

    Hasarı _fire_weapon() vuruş anında uygular; bu sınıf yalnızca görseldir.
    """

    LIFE = 0.32
    SEGS = 22                 # gövdeyi oluşturan nokta sayısı
    GHOSTS = 2                # arkada bırakılan hayalet kırbaç sayısı

    def __init__(self, player, ang, length, width, color=WHIP_COLOR, spin=1):
        self.p = player
        self.x, self.y = player.x, player.y
        self.ang = ang               # savurmanın ORTA açısı (baktığın yön)
        self.length = length
        self.width = max(6.0, float(width))
        self.color = color
        self.spin = 1 if spin >= 0 else -1   # saat yönü / tersi
        self.life = self.LIFE
        self.alive = True

    def update(self, dt, run):
        # Kabza oyuncunun elinde kalsın: her karede oyuncuya yeniden oturur.
        self.x, self.y = self.p.x, self.p.y
        self.life -= dt
        if self.life <= 0:
            self.alive = False

    # ---------------- geometri ----------------
    def _curve(self, f, segs=None):
        """Savurmanın f anındaki kabza ucu, kabza açısı ve gövde noktaları.

        f=0 savurmanın başı (kırbaç geride, toplu), f=1 sonu (tam açılmış).
        Gövde noktaları kabzadan uca doğru sıralıdır.
        """
        segs = segs or self.SEGS
        e = ease_out_cubic(clamp(f, 0.0, 1.0))
        swing = self.spin * WHIP_SWING * (2.0 * e - 1.0)
        a_grip = self.ang + swing * 0.30      # el, ucun yalnızca bir miktarı kadar döner
        a_tip = self.ang + swing
        # Boy: kırbaç savrulurken AÇILIR, ortalarda tam boyuna ulaşır.
        reach = self.length * (0.46 + 0.54 * ease_out_cubic(min(1.0, f * 1.35)))
        gx = self.x + math.cos(a_grip) * WHIP_GRIP
        gy = self.y + math.sin(a_grip) * WHIP_GRIP
        span = max(8.0, reach - WHIP_GRIP)
        pts = []
        for i in range(segs + 1):
            fr = i / segs
            # 1) Uca doğru savurma açısına yaklaşır (kabzaya yakın kısım geride
            #    kalır — kırbacın kıvrımını doğuran gecikme budur).
            a = lerp(a_grip, a_tip, fr ** 0.55)
            # 2) Ortası dışa doğru kabarır: düz bir yay değil, S kıvrımı.
            #    Savurma tamamlandıkça kabarma düzleşir, kırbaç gerilir.
            a -= self.spin * WHIP_CURL * math.sin(fr * math.pi) * (1.0 - e * 0.60)
            rr = span * fr
            pts.append((gx + math.cos(a) * rr, gy + math.sin(a) * rr))
        return (gx, gy), a_grip, pts

    @staticmethod
    def _ribbon(pts, w0, w1, power=1.05, off=0.0):
        """Nokta dizisini, kalınlığı w0'dan w1'e inen KAPALI çokgene çevirir.

        Kırbacı tek bir çokgen olarak çizmenin tek yolu bu: uç uca eklenen
        kalın çizgiler her eklemde yuvarlak bir uç bırakıp boncuk etkisi
        yapıyordu. off, orta çizgiyi dikeyde kaydırır (ışık şeridi için).
        """
        n = len(pts)
        if n < 2:
            return []
        left, right = [], []
        for i, (x, y) in enumerate(pts):
            fr = i / (n - 1.0)
            hw = lerp(w0, w1, fr ** power) * 0.5
            if i == 0:
                ax, ay = pts[1][0] - x, pts[1][1] - y
            elif i == n - 1:
                ax, ay = x - pts[n - 2][0], y - pts[n - 2][1]
            else:
                ax, ay = pts[i + 1][0] - pts[i - 1][0], pts[i + 1][1] - pts[i - 1][1]
            L = math.hypot(ax, ay) or 1.0
            ux, uy = -ay / L, ax / L          # birim dikey
            cx, cy = x + ux * off, y + uy * off
            left.append((cx + ux * hw, cy + uy * hw))
            right.append((cx - ux * hw, cy - uy * hw))
        right.reverse()
        return left + right

    # ---------------- çizim ----------------
    def draw(self, surf, t):
        k = clamp(self.life / self.LIFE, 0.0, 1.0)
        f = 1.0 - k
        body = self.color
        dark = scale_col(body, 0.30)
        mid = scale_col(body, 0.72)
        lite = WHIP_COLOR2
        w = self.width

        # 1) HAREKET İZİ — birkaç kare geriden gelen, sönen hayalet kırbaçlar.
        # Dünya yüzeyi saydam değil; bu yüzden alfa yerine rengi karartıyoruz.
        for gi in range(1, self.GHOSTS + 1):
            gf = f - gi * 0.085
            if gf <= 0.03:
                continue
            _, _, gpts = self._curve(gf, segs=12)
            dim = 0.58 * (1.0 - gi / (self.GHOSTS + 1.0)) * (0.30 + 0.70 * k)
            poly_aa(surf, self._ribbon(gpts, w * 0.44, 0.8), scale_col(lite, dim))

        grip, a_grip, pts = self._curve(f)

        # 2) KAMÇI — dört katman: kontur, koyu deri, açık deri, kenar ışığı.
        # Kalınlık kabzada w, uçta 1 pikselin altına iner: kırbaç uca doğru
        # gerçekten SİVRİLİR, eski hâlindeki gibi kalın bir hortum kalmaz.
        poly_aa(surf, self._ribbon(pts, w + 3.2, 2.0), OUTLINE)
        poly_aa(surf, self._ribbon(pts, w, 1.0), dark)
        poly_aa(surf, self._ribbon(pts, w * 0.78, 0.8), mid)
        poly_aa(surf, self._ribbon(pts, w * 0.52, 0.6), body)
        # Işık şeridi: gövdenin bir yanına kaçmış ince bir hat. Deriye yuvarlak
        # bir hacim veren tek çizgi bu.
        poly_aa(surf, self._ribbon(pts, w * 0.30, 0.5, off=-w * 0.24),
                scale_col(lite, 0.62 + 0.38 * f))

        # 3) KABZA — elde duran kısa, deri sargılı sap. Bilerek İNCE: gövdeden
        # biraz kalın ama oyuncunun üstünde şişkin bir topak bırakmayacak kadar.
        hw = w * 0.92
        hx = self.x - math.cos(a_grip) * WHIP_GRIP * 0.42
        hy = self.y - math.sin(a_grip) * WHIP_GRIP * 0.42
        thick_line(surf, (hx, hy), grip, hw + 2.6, OUTLINE)
        thick_line(surf, (hx, hy), grip, hw, scale_col(body, 0.34))
        leather_wrap(surf, (hx, hy), grip, hw * 0.92, n=3,
                     base=scale_col(body, 0.50))
        # kabzanın topuzu
        circle_aa(surf, hx, hy, hw * 0.46, OUTLINE)
        circle_aa(surf, hx, hy, hw * 0.33, scale_col(lite, 0.50))

        # 4) UÇ — ince kamçı ucu (fall) ve şaklama.
        ex, ey = pts[-1]
        px, py = pts[-2]
        dx, dy = ex - px, ey - py
        L = math.hypot(dx, dy) or 1.0
        ux, uy = dx / L, dy / L
        fall = 16.0 * (0.35 + 0.65 * f)
        tip = (ex + ux * fall, ey + uy * fall)
        thick_line(surf, (ex, ey), tip, 2.2, scale_col(lite, 0.85))
        add_glow(surf, tip[0], tip[1], 10 + 18 * f, lite, 0.28 + 0.34 * k)
        circle_aa(surf, tip[0], tip[1], 1.6 + 1.4 * f, lite)

        # ŞAKLAMA: yay tamamlanırken uçta parlama ve kıvılcımlar.
        if f > 0.58:
            crack = clamp((f - 0.58) / 0.42, 0.0, 1.0)
            add_glow(surf, tip[0], tip[1], 14 + 26 * crack, lite, 0.45 * crack)
            base_a = math.atan2(uy, ux)
            for i in range(5):
                a = base_a + random.uniform(-1.0, 1.0)
                ln = random.uniform(8, 26) * crack
                thick_line(surf, tip,
                           (tip[0] + math.cos(a) * ln, tip[1] + math.sin(a) * ln),
                           1.5, lite)



class SwordSlash:
    """EMANET'in çizdiği YAY: hızla açılıp sönen bir hilal.

    Hasarı _fire_weapon() vuruş anında uygular; bu sınıf yalnızca görseldir.
    Oyuncuyu TAKİP eder (yay 0.26 saniye yaşıyor ve oyuncu bu sürede
    kıpırdıyor; sabit kalsaydı kılıç elinden kopmuş gibi duruyordu).
    """

    LIFE = 0.26

    def __init__(self, player, ang, radius, half_arc, color=None):
        self.p = player
        self.x, self.y = player.x, player.y
        self.ang = ang
        self.radius = radius
        self.half = half_arc
        # Renk sabitleri bu sınıftan SONRA tanımlanıyor; varsayılanı burada
        # çözüyoruz ki sınıf gövdesi onlara erken el atmasın.
        self.color = color or EMANET_COLOR
        self.life = self.LIFE
        self.alive = True

    def update(self, dt, run):
        self.x, self.y = self.p.x, self.p.y
        self.life -= dt
        if self.life <= 0:
            self.alive = False

    def draw(self, surf, t):
        k = clamp(self.life / self.LIFE, 0.0, 1.0)
        # Yay ömrünün başında dar ve yakın, sonunda tam açık ve uzaktır:
        # kılıç gerçekten savruluyormuş gibi okunur.
        sweep = self.half * (0.35 + 0.65 * (1 - k))
        rad = self.radius * (0.66 + 0.34 * (1 - k))
        n = 15
        outer = []
        for i in range(n):
            a = self.ang - sweep + 2 * sweep * i / (n - 1.0)
            outer.append((self.x + math.cos(a) * rad, self.y + math.sin(a) * rad))
        # İNCE bir hilal: dolgulu geniş bir bant yerine üst üste üç şerit.
        # Dolgu, kılıcı yerde duran gri bir dilim gibi gösteriyordu.
        for f, w0, colr in ((0.86, 2.0, scale_col(self.color, 0.32 + 0.30 * k)),
                            (0.94, 3.0, scale_col(self.color, 0.55 + 0.45 * k)),
                            (1.00, 2.0 + 4.0 * k, scale_col(EMANET_COLOR2,
                                                            0.55 + 0.45 * k))):
            band = [(self.x + (px - self.x) * f, self.y + (py - self.y) * f)
                    for px, py in outer]
            # Uçlarda incelip ortada kalınlaşsın: bir kılıç darbesinin izi.
            for i in range(len(band) - 1):
                g = abs(i / (len(band) - 2.0) - 0.5) * 2.0
                thick_line(surf, band[i], band[i + 1],
                           max(1.0, w0 * (1.0 - 0.75 * g)), colr)
        # yayın ucunda kıvılcım
        ex, ey = outer[-1]
        add_glow(surf, ex, ey, 22 * k + 8, EMANET_COLOR2, 0.38 * k)
        for i in range(3):
            a = self.ang + sweep + random.uniform(-0.4, 0.4)
            ln = random.uniform(6, 18) * k
            thick_line(surf, (ex, ey), (ex + math.cos(a) * ln, ey + math.sin(a) * ln),
                       1.5, EMANET_COLOR2)


# =====================================================================
# KALKAN ve PENTAGRAM  (çizim yardımcıları)
# =====================================================================

BOOK_COLOR = (168, 152, 255)
BOOK_COLOR2 = (246, 232, 190)
PENTA_COLOR = (238, 78, 122)
PENTA_COLOR2 = (255, 182, 208)

# --- KALKAN (eski "kitap kalkanı") ---
# Kitaplar kalkan olmaktan çıktı: artık çevrende gerçek KALKANLAR dönüyor.
# Anahtar hâlâ "book": eski kayıtlarda açılmış/kapatılmış silah listeleri bu
# anahtarla tutuluyor, değiştirilse oyuncular silahı kaybederdi.
SHIELD_COLOR = (150, 176, 214)
SHIELD_COLOR2 = (236, 246, 255)
SHIELD_TRIM = (226, 186, 98)          # kalkanın altın kaplaması

# --- EMANET (kılıç) ---
EMANET_COLOR = (214, 226, 246)
EMANET_COLOR2 = (255, 252, 226)

# --- GÖRÜNMEZLİK PELERİNİ ---
CLOAK_COLOR = (132, 120, 214)
CLOAK_COLOR2 = (214, 206, 255)


def _shield_half_profile(r, n=8):
    """Kalkanın üstten sivri alt uca yarım profili (x>=0), üstten alta sıralı.

    u=0 tepe, u=1 sivri uç. 0..0.40 arası tepeden en geniş noktaya yumuşak
    açılır (yuvarlak omuz), 0.40..1.0 arası en geniş noktadan sivri uca
    yumuşak daralır (klasik kalkan/"heater shield" silüeti).
    """
    top_y, bot_y = -r * 0.92, r * 1.30
    span = bot_y - top_y
    pts = []
    for i in range(n + 1):
        u = i / n
        yy = top_y + span * u
        if u < 0.40:
            f = u / 0.40
            w = lerp(r * 0.58, r * 1.08, math.sin(f * math.pi * 0.5))
        else:
            f = (u - 0.40) / 0.60
            w = r * 1.08 * max(0.0, 1.0 - f) ** 1.4
        pts.append((w, yy))
    return pts


def _shield_outline_pts(r, rot=0.0):
    """Kalkanın TAM (kapalı) yerel ana hattı — merkez (0,0) etrafında.

    Sağ profil + aynısının aynalanmışı: tepeden sivri uca, sivri uçtan
    tekrar tepeye, kapalı bir çokgen. Küçük rot açısıyla hafifçe döndürülür
    (yalpalama animasyonu için)."""
    right = _shield_half_profile(r)
    left = [(-px, py) for px, py in reversed(right)]
    pts = right + left
    if rot:
        c, s = math.cos(rot), math.sin(rot)
        pts = [(px * c - py * s, px * s + py * c) for px, py in pts]
    return pts


def draw_shield_book(surf, x, y, ang, k=1.0, charged=True, t=0.0, phase=0.0):
    """Oyuncunun çevresinde süzülen KALKAN.

    Eskiden burada bir KİTAP çiziliyordu. Kitap kalkanı kaldırıldı: artık
    oyuncunun etrafında dövme, altın kaplamalı KALKANLAR dönüyor. Mekanik
    birebir aynı (her kalkan bir mermiyi yutar), değişen yalnızca kimlik
    ve çizim.

    v3.9: kalkan artık düz bir DAİRE değil — yuvarlak omuzlu, sivri uçlu
    gerçek bir KALKAN SİLÜETİ (klasik "heater shield"). Altın kaplama,
    perçinler ve pah ışığı artık bu silüetin kendi hattını TAKİP EDİYOR;
    eskiden bağımsız bir daire üstüne çizildikleri için oransız ve
    özensiz duruyorlardı.

    ÇİZİM KURALI: kalkan ekranda DİK durur, yalnızca hafifçe yalpalar.
    Oyunu tepeden gördüğümüz için yörünge açısıyla döndürülen bir kalkan
    yere yatmış bir tabak gibi okunuyordu.

    charged False ise kalkan bir mermiyi yeni savuşturmuştur: soluk bir
    hayalet olarak çizilir ve yeniden dolmasını bekler.
    """
    r = 13.0 * k
    tilt = math.sin(t * 2.2 + phase) * 0.10
    bob = math.sin(t * 2.6 + phase * 1.3) * 1.6 * k
    y = y + bob

    if charged:
        face = SHIELD_COLOR
        face_lo = scale_col(SHIELD_COLOR, 0.42)
        trim = SHIELD_TRIM
        boss_hi = SHIELD_COLOR2
        add_glow(surf, x, y, r * 2.0, SHIELD_COLOR,
                 0.30 + 0.14 * math.sin(t * 4 + phase))
    else:
        face = scale_col(SHIELD_COLOR, 0.30)
        face_lo = scale_col(SHIELD_COLOR, 0.15)
        trim = scale_col(SHIELD_TRIM, 0.28)
        boss_hi = scale_col(SHIELD_COLOR2, 0.30)

    local = _shield_outline_pts(r, tilt)
    world = [(x + px, y + py) for px, py in local]

    # 1) kontur/gölge — hafif aşağı kaydırılmış koyu silüet
    poly_aa(surf, [(x + px, y + py + 1.4 * k) for px, py in local], OUTLINE)

    # 2) gövde — merkeze doğru küçültülmüş katmanlarla pah ışığı (madalyon hissi)
    for i in range(5, 0, -1):
        f = i / 5.0
        poly_aa(surf, [(x + px * f, y + py * f) for px, py in local],
                mix_col(face, face_lo, f))

    # 3) altın kaplama — kalkanın KENDİ hattını izleyen dış kontur + iç bilezik
    poly_edge(surf, world, scale_col(trim, 0.72), w=max(1, int(r * 0.16)))
    poly_edge(surf, [(x + px * 0.88, y + py * 0.88) for px, py in local],
              trim, w=max(1, int(r * 0.08)))

    # 4) perçinler — kalkanın hattı üstünde, eşit aralıklı
    n = len(local)
    for idx in (0, n // 8, n // 4, n // 2, n // 2 + n // 8, n // 2 + n // 4,
                (3 * n) // 4, (7 * n) // 8):
        px, py = local[idx % n]
        f = 0.90
        circle_aa(surf, x + px * f, y + py * f, max(1.0, r * 0.09),
                  scale_col(trim, 1.12))

    # 5) göbek (umbo): kalkanın üst-orta kesimine yakın kubbe + tepe parlaması
    ux, uy = x, y - r * 0.14
    circle_aa(surf, ux, uy, r * 0.32, scale_col(face_lo, 0.85))
    disc_grad(surf, ux - r * 0.08, uy - r * 0.10, r * 0.27, boss_hi,
              scale_col(face_lo, 1.05), 5)
    if charged:
        circle_aa(surf, ux - r * 0.10, uy - r * 0.12, max(1.0, r * 0.08), WHITE)
        # 6) DOLU kalkanın üstünde süzülen tılsım zerreleri
        for i in range(2):
            ph = (t * 0.9 + phase * 0.3 + i * 0.5) % 1.0
            sy = y - r * 1.35 - ph * 12 * k
            sx = x + math.sin(t * 3 + i * 2.2 + phase) * 5 * k
            circle_aa(surf, sx, sy, max(1.0, 2.0 * k * (1 - ph)), SHIELD_COLOR2)
    else:
        # boşta: yüzeyde bir çatlak izi kalır
        thick_line(surf, (x - r * 0.30, y - r * 0.10), (x + r * 0.20, y + r * 0.50),
                   max(1.0, r * 0.07), scale_col(SHIELD_COLOR, 0.42))


def draw_pentagram(surf, cx, cy, r, ang, t=0.0, color=PENTA_COLOR, color2=PENTA_COLOR2):
    """Oyuncunun ayağının altında dönen pentagram alanı.

    Doğrudan hedef yüzeye çizer. 8. seviyede yarıçap ~356 px oluyor; buna
    geçici bir SRCALPHA yüzeyi ayırmak (700x700) tek başına kare süresinin
    büyük kısmını yiyordu. Saydam dolgu önbellekli blit_disc ile, kalan
    çizgiler karartılmış donuk renkle çiziliyor.
    """
    if r < 6:
        return
    pulse = 0.5 + 0.5 * math.sin(t * 3.1)
    # 1) alanın kendisi — kanla dolu soluk daire
    blit_disc(surf, cx, cy, r, color, int(30 + 14 * pulse))
    add_glow(surf, cx, cy, r * 0.75, color, 0.16 + 0.08 * pulse)
    # 2) iki çember
    pygame.draw.circle(surf, scale_col(color, 0.68), (int(cx), int(cy)), int(r), 3)
    pygame.draw.circle(surf, scale_col(color2, 0.48), (int(cx), int(cy)), int(r * 0.88), 2)
    # 3) beş köşeli yıldız — köşeleri atlayarak bağlanır
    pts = []
    for i in range(5):
        a = ang - math.pi / 2 + i * math.tau / 5
        pts.append((cx + math.cos(a) * r * 0.86, cy + math.sin(a) * r * 0.86))
    order = (0, 2, 4, 1, 3, 0)
    star_col = scale_col(color2, 0.60 + 0.25 * pulse)
    for i in range(5):
        pygame.draw.line(surf, star_col, pts[order[i]], pts[order[i + 1]], 3)
    # 4) köşelerde yanan mumlar
    for (px, py) in pts:
        pygame.draw.circle(surf, color2, (int(px), int(py)), 4)
        pygame.draw.circle(surf, WHITE, (int(px), int(py)), 2)
    # 5) çember boyunca dönen işaretler
    rune_col = scale_col(color, 0.55)
    for i in range(12):
        a = -ang * 0.6 + i * math.tau / 12
        ca, sa = math.cos(a), math.sin(a)
        pygame.draw.line(surf, rune_col, (cx + ca * r * 0.94, cy + sa * r * 0.94),
                         (cx + ca * r * 1.02, cy + sa * r * 1.02), 2)


