# --- GÖRÜNMEZLİK PELERİNİ ---
CLOAK_BASE_CD = 60.0            # 1. seviyede iki görünmezlik arası (saniye)
CLOAK_CD_PER_LEVEL = 1.0        # her seviyede beklemeden düşen saniye
CLOAK_MIN_CD = 36.0             # 25. seviyede ulaşılan taban
CLOAK_DUR = 5.0                 # görünmez kalma süresi (saniye)
CLOAK_DUR_PER_LEVEL = 0.10      # her seviyede süreye eklenen saniye


def whip_arc(lvl):
    """KIRBACIN taradığı yarım açı — dar başlar, seviyeyle genişler."""
    return min(WHIP_ARC_MAX, WHIP_ARC + WHIP_ARC_PER_LEVEL * weapon_growth(lvl))


def whip_reach(lvl):
    """KIRBACIN erişimi — seviyeyle belirgin biçimde uzar."""
    return WHIP_LEN + WHIP_LEN_PER_LEVEL * weapon_growth(lvl)


def emanet_radius(lvl):
    """EMANET'in taradığı yayın yarıçapı — seviyeyle ölçülü büyür."""
    return EMANET_BASE_R + EMANET_R_PER_LEVEL * weapon_growth(lvl)


def emanet_arc(lvl):
    """EMANET'in taradığı yarım açı (radyan) — seviyeyle genişler."""
    return min(EMANET_ARC_MAX,
               EMANET_BASE_ARC + EMANET_ARC_PER_LEVEL * weapon_growth(lvl))


def is_armored(e):
    """Düşman ZIRHLI mı? EMANET bu düşmanlara ek hasar vurur.

    Zırhlı sayılanlar: zırh yüzdesi olanlar (25. dalga sonrası arena
    yaratıkları ve bütün patronlar), KALKANLI siperciler, sancaktar ve
    TANK/ELİT gövdeler.
    """
    if getattr(e, "armor", 0.0) > 0.005:
        return True
    if getattr(e, "guard_of", None) is not None:
        return True
    if getattr(e, "is_mini", False) or getattr(e, "is_boss", False):
        return True
    return getattr(e, "kind", "") in ("tank", "brute", "elite", "shieldman")


def cloak_cooldown(lvl):
    """İki görünmezlik arasındaki süre — her seviyede 3 saniye kısalır."""
    return max(CLOAK_MIN_CD, CLOAK_BASE_CD - CLOAK_CD_PER_LEVEL * weapon_growth(lvl))


def cloak_duration(lvl):
    """Görünmez kalma süresi."""
    return CLOAK_DUR + CLOAK_DUR_PER_LEVEL * weapon_growth(lvl)


# PUSU HASARI (v3.22). PELERİN, oyunda HİÇ hasara katkısı olmayan tek
# silahtı: gerçek koşuda ölçüldüğünde hem kalabalığa hem patrona 0.0 DPS
# veriyordu, ama dört silah yuvasından birini tutuyordu. İşi (sıradan
# yaratıkları dondurmak) savunma tarafında gerçekten güçlü, o yüzden
# kaldırmak yerine kendi fantezisine uygun bir ödül eklendi: görünmezken
# vuruşların daha ağır. Böylece pelerin "saklanma düğmesi" değil, "pusu
# penceresi" oluyor — oyuncu o saniyelerde kaçmak yerine saldırıyor.
#   1. sv +%35 ... 25. sv +%95 (açık kalma oranı %8.3 -> %20.6 olduğu için
#   ortalamaya katkısı +%3 ile +%19 arası; yuvayı hak edecek kadar, dengeyi
#   bozmayacak kadar).
CLOAK_AMBUSH_BASE = 0.35
CLOAK_AMBUSH_PER_LEVEL = 0.025


def cloak_ambush_bonus(lvl):
    """Görünmezken hasara eklenen oran (0.35 = +%35)."""
    if lvl <= 0:
        return 0.0
    return CLOAK_AMBUSH_BASE + CLOAK_AMBUSH_PER_LEVEL * weapon_growth(lvl)


def book_slot_pos(p, i, n_book):
    """i numaralı KALKANIN dünya konumu ve yörünge açısı.

    n_book = o anda dönen kalkan SAYISI (silahın seviyesi değil; bkz.
    weapon_count). Kalkanlar oyuncunun çevresinde eşit aralıkla dizilir ve
    hep birlikte döner; böylece hem çizim hem de mermi savuşturma aynı
    konumu kullanır.
    """
    a = p.book_angle + i * math.tau / max(1, n_book)
    # Hafif elips: kalkanlar tepe noktasında biraz yakın görünür, çemberin
    # yere yatık olduğu hissini verir.
    return (p.x + math.cos(a) * BOOK_ORBIT_R,
            p.y + math.sin(a) * BOOK_ORBIT_R * 0.72,
            a)


def penta_sear_hp_frac(lvl):
    """Mühre ilk adımda yaratığın canından kesilen ORAN (patronlar hariç)."""
    return min(PENTA_SEAR_HP_MAX,
               PENTA_SEAR_HP + PENTA_SEAR_HP_PER_LEVEL * weapon_growth(lvl))


def _penta_step(table, lvl):
    return table[clamp(int(lvl) - 1, 0, len(table) - 1)]


def penta_sear_cap(lvl):
    """İLK ADIM vuruşunun yaratığın O ANKİ canından alabileceği EN ÇOK oran.

    1.0'dan küçükse mühür o yaratığı ilk temasta ÖLDÜREMEZ — canını düşürür,
    gerisini mührün içindeki sürekli yanma halleder. 11. seviyeden itibaren
    1.0 olur (yaklaşık 17. seviye), yani mühür yeniden tek atmaya başlar —
    ama artık bu bir başlangıç gücü değil, uzun bir yükseltmenin ödülü.
    """
    return min(1.0, PENTA_SEAR_CAP + PENTA_SEAR_CAP_PER_LEVEL * weapon_growth(lvl))


def penta_bat_sear_cap(lvl):
    """Yarasanın canından İLK ADIM vuruşuyla gidebilecek en çok oran."""
    return _penta_step(PENTA_BAT_SEAR_CAP, lvl)


def penta_bat_tick_mult(lvl):
    """Yarasaya işleyen SÜREKLİ hasarın çarpanı."""
    return _penta_step(PENTA_BAT_TICK, lvl)


def is_penta_bat(e):
    """Bu yaratık YARASA mı? (pentagramın yarasaya özel freni için)"""
    return getattr(e, "shape", "") == PENTA_BAT_SHAPE


def penta_radius(lvl):
    """PENTAGRAM alanının yarıçapı — her seviyede büyür."""
    return PENTA_BASE_R + PENTA_R_PER_LEVEL * weapon_growth(lvl)


def shoe_radius(lvl):
    """BARAN'IN PAPUCU'nun bıraktığı ateş halkasının başlangıç yarıçapı."""
    return SHOE_BASE_R + SHOE_R_PER_LEVEL * weapon_growth(lvl)


def shoe_life(lvl):
    """Ateş halkasının ömrü — seviyeye göre (bkz. SHOE_LIFE_STEPS)."""
    g = weapon_growth(lvl)
    if g <= len(SHOE_LIFE_STEPS) - 1:
        i = int(g)
        f = g - i
        a = SHOE_LIFE_STEPS[i]
        b = SHOE_LIFE_STEPS[min(i + 1, len(SHOE_LIFE_STEPS) - 1)]
        return lerp(a, b, f)
    return SHOE_LIFE_STEPS[-1] + SHOE_LIFE_PER_LEVEL * (g - (len(SHOE_LIFE_STEPS) - 1))


def draw_pentagram_field(surf, p, t):
    """Oyuncunun ayağının altındaki PENTAGRAM mührü (varsa)."""
    lvl = p.weapons.get("pentagram", 0)
    if lvl <= 0:
        return
    draw_pentagram(surf, p.x, p.y, penta_radius(lvl), p.penta_angle, t)


def draw_shield_books(surf, p, t, layer="front"):
    """Oyuncunun çevresinde dönen KALKANLAR (varsa).

    layer="back"  : yörüngenin ARKA yarısındaki kalkanlar — oyuncudan ÖNCE
    layer="front" : ÖN yarıdakiler — oyuncudan SONRA
    İkisi ayrı çizilince kalkanlar gerçekten oyuncunun ETRAFINDA dönüyormuş
    gibi okunuyor; hepsi üstte çizilince oyuncunun önünde asılı duruyorlardı.

    Mermiyi yeni savuşturmuş (boşa çıkmış) kalkan soluk çizilir: oyuncu kaç
    kalkanının kaldığını tek bakışta görsün.
    """
    lvl = p.weapons.get("book", 0)
    if lvl <= 0:
        return
    n_book = weapon_count(lvl)
    for i in range(n_book):
        bx, by, a = book_slot_pos(p, i, n_book)
        back = math.sin(a) < 0
        if back != (layer == "back"):
            continue
        # Derinlik: arkadaki kalkan küçülür, öndeki büyür.
        depth = (math.sin(a) + 1.0) * 0.5          # 0 = en arka, 1 = en ön
        k = (0.82 + 0.30 * depth) * (1.0 + 0.012 * (lvl - 1))
        charged = not (i < len(p.book_charges) and p.book_charges[i] > 0)
        draw_shield_book(surf, bx, by, a, k, charged, t, phase=i * 1.7)


# =====================================================================
# SİLAH AÇILIŞLARI
# ---------------------------------------------------------------------
# Silahlar tıpkı kitaplar gibi GÖREVLE açılır; açılışı tamamlanmamış bir
# silah seviye atlama ekranında asla görünmez. Şart değerlendirmesi kitapların
# altyapısını (rq_* / book_req_state) aynen kullanır, böylece tek bir yerde
# tanımlı kalır.
# =====================================================================


def weapon_reqs(w):
    unl = w.get("unlock")
    return list(unl.get("reqs", [])) if unl else []


def weapon_progress(save, w):
    """Silahın görev ilerlemesi: (tamamlanan, toplam, hepsi tamam mı)."""
    reqs = weapon_reqs(w)
    if not reqs:
        return 1, 1, True
    done = sum(1 for r in reqs if book_req_state(save, r)[2])
    return done, len(reqs), done >= len(reqs)


def weapon_frac(save, w):
    """Silahın görevlerindeki ortalama ilerleme (0..1) — çubuk ve sıralama için."""
    reqs = weapon_reqs(w)
    if not reqs:
        return 1.0
    tot = 0.0
    for r in reqs:
        cur, need, done, _ = book_req_state(save, r)
        tot += 1.0 if done else clamp(cur / max(1, need), 0.0, 1.0)
    return tot / len(reqs)


# Oyuncunun bir koşuda taşıyabileceği en fazla silah sayısı. Seviye atlama
# ekranı bu sayıya ulaşılınca yeni silah ÖNERMEZ; sandıklar da yalnızca
# oyuncunun seçtiği bu silahları yükseltir.
MAX_RUN_WEAPONS = 4
# Oyuncunun "bu bana gelmesin" diyerek kapatabileceği en fazla silah sayısı.
MAX_MUTED_WEAPONS = 4


def weapon_max_level(w):
    """Silahın çıkabileceği en yüksek seviye.

    Silahın kendi "max" alanı varsa o geçerlidir (örn. HORTUM 5'te durur);
    yoksa ortak tavan WEAPON_MAX_LEVEL kullanılır.
    """
    return int(w.get("max", WEAPON_MAX_LEVEL))


def weapon_cooldown(w, level):
    """Silahın iki atışı arasındaki süre.

    Normalde seviye arttıkça kısalır. Bekleme süresi TASARIM GEREĞİ sabit
    kalması gereken silahlar (BALTA 5 sn, ZEMZEM 10 sn, HORTUM 15 sn) satırına
    cdl=1.0 yazar; böylece "şu kadar saniyede bir" sözü her seviyede tutar.
    """
    k = float(w.get("cdl", WEAPON_CD_PER_LEVEL))
    return max(0.22, w["cd"] * (k ** weapon_growth(level)))


def weapon_damage(player, w, level):
    """Silahın vuruş hasarı — OYUNCUNUN o anki hasarına göre ölçeklenir.

    Böylece silah, alındığı dalgada güçlü olup 10 dalga sonra çöpe dönmez;
    oyuncunun güç eğrisini takip eder.

    DENGE: seviye başına hasar artışı silaha göre değişir (dpl alanı). Sayısı
    ya da alanı seviyeyle büyüyen silahlarda (BALTA, KIRBAÇ, KİTAP, PAPUÇ,
    ZEMZEM) tek vuruşun hasarı daha yavaş artar — yoksa "iki kat balta x iki
    kat hasar x iki kat sıklık" üst üste binip 8. seviyede oyunu anlamsız
    kılıyordu.
    """
    dpl = float(w.get("dpl", WEAPON_DMG_PER_LEVEL))
    return (player.eff_dmg() * w["dmg"] * WEAPON_DMG_GLOBAL
            * (1.0 + dpl * WEAPON_DPL_SCALE * weapon_growth(level)))


# =====================================================================
# TEK-ATMA FRENİ  (v3.16)
# ---------------------------------------------------------------------
# İSTEK: "HİÇBİR EŞYA TEK ATMAMALI" — ve özel olarak: hortum 1. seviyede bile
# her şeyi buharlaştırıyordu, kırbaç da öyle.
#
# Çözüm, hasarı tek tek kısmak değil (o zaman silahlar geç oyunda çöpe
# dönüyor), ORTAK BİR FREN koymak: bir silahın TEK vuruşu, yaratığın O ANKİ
# canının en çok belirli bir oranını alabilir. Oran 1.0'ın altındayken o
# vuruş yaratığı ÖLDÜREMEZ — canını düşürür, gerisini bir sonraki vuruş /
# tik halleder. Oran yaratığın SIKLETİNE ve silahın SEVİYESİNE bağlıdır:
#
#   HAFİF  (mavi küçükler, koşucular, imp — "fare/yarasa")
#       1. seviyede canın %80'i, 10. SEVİYEDE fren tamamen kalkar.
#       Yani 10. seviyeden sonra bunlar yeniden tek atılır.
#   ORTA   (kırmızı, sarı, tazı, kâhin, yağmacı)
#       1. seviyede %68, 18. seviyede fren kalkar.
#   AĞIR   (tank, gürz, elit, siperci, sancaktar, golem, kasap, gardiyan ve
#           zırhı olan her şey — "tank")
#       %46'dan başlar, 25. seviyede ancak %74'e çıkar: HİÇBİR seviyede
#       tek atılamaz. Tankı devirmek her zaman birkaç vuruş ister.
#
# PATRONLAR frenden muaftır: canları zaten oyuncunun gücüne göre
# ölçekleniyor (bkz. scale_bosses_to_player), fren orada anlamsız olurdu.
#
# Fren PENTAGRAM'ın zaten var olan kendi freniyle (penta_sear_cap) aynı
# mantıkta çalışır; o silah kendi tablosunu kullanmaya devam eder.
# =====================================================================
ENEMY_WEIGHT_CLASS = {
    "blue": "frail", "sprinter": "frail", "imp": "frail",
    "red": "normal", "yellow": "normal", "hound": "normal",
    "bomber": "frail", "healer": "normal",
    "wizard": "normal", "stinger": "frail",
    "seer": "normal", "reaver": "normal",
    "tank": "tough", "brute": "tough", "elite": "tough",
    "shieldman": "tough", "herald": "tough",
    "golem": "tough", "butcher": "tough", "warden": "tough",
}
# (1. seviyedeki oran, frenin tamamen kalktığı seviye, hiç kalkmıyorsa tavan)
ONESHOT_CAP_TABLE = {
    "frail":  (0.80, 10, 1.0),
    "normal": (0.68, 18, 1.0),
    "tough":  (0.46, None, 0.74),
}


def enemy_weight_class(e):
    """Yaratığın SIKLETİ: "frail" | "normal" | "tough".

    Zırhı olan, kalkanlı, elit ya da yarı patron olan her şey AĞIR sayılır —
    türü tabloda ne yazarsa yazsın.
    """
    if getattr(e, "armor", 0.0) > 0.005:
        return "tough"
    if getattr(e, "guard_of", None) is not None:
        return "tough"
    if getattr(e, "is_mini", False):
        return "tough"
    return ENEMY_WEIGHT_CLASS.get(getattr(e, "kind", ""), "normal")


def oneshot_cap(e, lvl):
    """Tek vuruşun yaratığın O ANKİ canından alabileceği EN ÇOK oran (0..1].

    1.0 dönerse fren yoktur (vuruş öldürebilir).
    """
    if getattr(e, "is_boss", False):
        return 1.0
    base, gate, top = ONESHOT_CAP_TABLE[enemy_weight_class(e)]
    lvl = max(1, int(lvl))
    if gate is None:
        # Fren hiç kalkmaz: taban ile tavan arasında seviyeyle yumuşak yürür.
        f = clamp(weapon_growth(lvl) / max(1.0, WEAPON_MAX_LEVEL - 1), 0.0, 1.0)
        return clamp(lerp(base, top, f), 0.0, 0.999)
    if lvl >= gate:
        return 1.0
    return clamp(lerp(base, 1.0, (lvl - 1) / float(gate - 1)), 0.0, 1.0)


# FRENİN İKİNCİ VURUŞTA BIRAKTIĞI (v3.18)
# ---------------------------------------------------------------------
# Fren "tek vuruşta ölmesin" içindi ama yan etkisi çirkindi: EMANET gibi
# hızlı silahlar düşmanı her vuruşta canının bir oranına indiriyor, yaratık
# bir türlü ölmüyor ve ekranda "0" hasar yiyen, kıl payı canla gezinen
# yaratıklar kalıyordu.
#
# İki kural eklendi:
#   1) BİR KERELİK: fren bir yaratığa yalnızca BİR KEZ uygulanır. İlk vuruş
#      onu öldürmez; İKİNCİ vuruş serbesttir ve öldürür. "İlk vuruşta tek
#      atıyorsa ikincide atsın" tam olarak bu.
#   2) MERHAMET EŞİĞİ: fren sonrası yaratık canının %6'sından azıyla
#      kalacaksa hiç frenlenmez, vuruş onu bitirir. Böylece "1 canla kalan,
#      0 hasar yiyen düşman" diye bir şey olmuyor.
#
# Yani kural artık "hiçbir eşya tek atmasın" değil, "hiçbir eşya TEK VURUŞTA
# atmasın": ilk vuruş yaratığı yere serer, ikinci vuruş bitirir. Tank da
# fare de aynı kuraldan geçer; fark yalnızca ilk vuruşun ne kadarını
# götürdüğünde (bkz. ONESHOT_CAP_TABLE).
ONESHOT_MERCY = 0.06            # bu orandan az canla bırakma, bitir


def cap_oneshot(e, dmg, lvl):
    """Hasarı tek-atma frenine göre kırpar (bkz. oneshot_cap).

    Fren yaratık başına BİR KEZ işler; ikinci vuruş serbesttir.
    """
    if lvl is None or dmg <= 0:
        return dmg
    # Bu yaratık frenini zaten yedi mi? Yediyse artık serbest.
    if getattr(e, "_oneshot_used", False):
        return dmg
    cap = oneshot_cap(e, lvl)
    if cap >= 1.0:
        return dmg
    hp = max(0.0, getattr(e, "hp", 0.0))
    capped = hp * cap
    if dmg <= capped:
        return dmg                      # vuruş zaten frenin altında
    # MERHAMET: geriye kıl payı can kalacaksa frenleme, bitir.
    if hp - capped <= hp * ONESHOT_MERCY:
        return dmg
    e._oneshot_used = True
    return capped


class BossChest:
    """Patron ölünce düşen sandık. Oyuncu dokununca açılır ve silah verir."""

    def __init__(self, x, y, boss_name=""):
        self.x, self.y = x, y
        self.r = 26
        self.t = 0.0
        self.open_t = 0.0          # açılma canlandırması
        self.opened = False
        self.taken = False         # ödül verildi mi (RunState işler)
        self.alive = True
        self.boss_name = boss_name
        self.bob = random.uniform(0, math.tau)

    def in_range(self, p):
        return dist(self.x, self.y, p.x, p.y) < self.r + p.radius + 10

    def update(self, dt, player):
        self.t += dt
        if self.opened:
            self.open_t += dt
            if self.open_t > 1.1:
                self.alive = False
            return
        if player.alive and self.in_range(player):
            self.opened = True
            self.open_t = 0.0

    def draw(self, surf, t):
        bob = math.sin(t * 2.4 + self.bob) * 3.0
        x, y = self.x, self.y + bob
        k = clamp(self.open_t / 0.4, 0.0, 1.0) if self.opened else 0.0
        surf.blit(shadow_sprite(int(self.r * 2)), (int(x - self.r), int(self.y + self.r * 0.5)))
        add_glow(surf, x, y, self.r * (2.0 + 1.6 * k), GOLD, 0.35 + 0.18 * math.sin(t * 3) + 0.4 * k)

        w, h = self.r * 1.7, self.r * 1.05
        # --- gövde ---
        base = pygame.Rect(int(x - w), int(y - h * 0.25), int(w * 2), int(h * 1.35))
        pygame.draw.rect(surf, OUTLINE, base.inflate(6, 6), border_radius=6)
        pygame.draw.rect(surf, (126, 78, 42), base, border_radius=6)
        pygame.draw.rect(surf, (86, 52, 28), base, width=2, border_radius=6)
        for i in (-1, 1):
            pygame.draw.line(surf, (92, 58, 32), (x + i * w * 0.45, base.top + 3),
                             (x + i * w * 0.45, base.bottom - 3), 3)
        # --- kapak (açılınca arkaya devrilir) ---
        lid_lift = h * 1.5 * k
        lid = pygame.Rect(int(x - w), int(y - h * 0.95 - lid_lift), int(w * 2), int(h * 0.85))
        pygame.draw.rect(surf, OUTLINE, lid.inflate(6, 6), border_radius=7)
        pygame.draw.rect(surf, (150, 96, 52), lid, border_radius=7)
        pygame.draw.rect(surf, GOLD, lid, width=2, border_radius=7)
        # --- altın kilit ---
        pygame.draw.rect(surf, GOLD, (int(x - 7), int(y - h * 0.28 - lid_lift * 0.4), 14, 16),
                         border_radius=3)
        pygame.draw.circle(surf, (120, 80, 20), (int(x), int(y - h * 0.20 - lid_lift * 0.4)), 3)
        # --- altın bantlar ---
        pygame.draw.line(surf, GOLD, (base.left + 2, base.top + 2), (base.right - 2, base.top + 2), 3)

        if self.opened:
            # açılırken içinden ışık sütunu ve kıvılcımlar fışkırır
            beam = pygame.Surface((int(w * 2), int(h * 6)), pygame.SRCALPHA)
            pygame.draw.polygon(beam, (255, 225, 140, int(150 * (1 - k * 0.4))),
                                [(w * 0.65, beam.get_height()), (w * 1.35, beam.get_height()),
                                 (w * 2.0, 0), (0, 0)])
            surf.blit(beam, (int(x - w), int(y - h * 6)))
            for i in range(8):
                a = t * 3 + i * math.tau / 8
                rr = self.r * (0.5 + 1.8 * k)
                blit_disc(surf, x + math.cos(a) * rr, y + math.sin(a) * rr * 0.6,
                          3.2 * (1 - k * 0.6), (255, 230, 150), int(220 * (1 - k)))
        else:
            # kapalıyken: yukarı süzülen altın zerreler + "YAKLAŞ" ipucu
            for i in range(4):
                ph = (t * 0.8 + i * 0.25 + self.bob) % 1.0
                sx_ = x + math.sin(t * 2 + i * 2.1) * self.r * 0.8
                sy_ = y - self.r * 0.4 - ph * self.r * 2.2
                blit_disc(surf, sx_, sy_, max(1.0, 3.0 * (1 - ph)), (255, 225, 140),
                          int(210 * (1 - ph)))
            draw_text(surf, L("ui.chest"), (x, y - self.r * 2.4), 13, GOLD,
                      bold=True, center=True)
            draw_text(surf, L("ui.chest_hint"), (x, y - self.r * 1.75), 10, TEXT_DIM,
                      center=True, shadow=False)


