# =====================================================================
# MARKA GÖRSELLERİ — ARENA BONK logosu ve ikonu  (v3.26)
# ---------------------------------------------------------------------
# Görseller dosyanın SONUNDAKİ EMBED_* sabitlerinde base64 olarak duruyor
# (tools/make_assets.py üretir). Neden gömülü: oyun tek bir .exe olarak
# dağıtılıyor; yanında resim klasörü taşımak gerekmesin, klasör eksik
# kalırsa logo "kaybolmasın". Çözülemezse (bozuk veri vb.) None döner ve
# çağıran yer eski yazı başlığına düşer — hiçbir şey çökmez.
# =====================================================================
_BRAND_CACHE = {}


def brand_image(name):
    """'logo' | 'icon' | 'badge' — ham (ölçeklenmemiş) yüzey ya da None."""
    if name in _BRAND_CACHE:
        return _BRAND_CACHE[name]
    img = None
    try:
        data = {"logo": EMBED_LOGO_PNG, "icon": EMBED_ICON_PNG,
                "badge": EMBED_BADGE_PNG}[name]
        raw = base64.b64decode("".join(data.split()))
        img = pygame.image.load(io.BytesIO(raw), "brand.png")
        if pygame.display.get_surface() is not None:
            img = img.convert_alpha()
    except Exception:
        img = None
    _BRAND_CACHE[name] = img
    return img


def brand_scaled(name, w=None, h=None):
    """Logoyu/ikonu istenen genişliğe (ya da yüksekliğe) ölçekler, önbellekler."""
    key = (name, None if w is None else int(w), None if h is None else int(h))
    img = _BRAND_CACHE.get(key)
    if img is not None:
        return img
    src = brand_image(name)
    if src is None:
        return None
    sw, sh = src.get_size()
    if w is not None:
        size = (int(w), max(1, int(sh * w / sw)))
    else:
        size = (max(1, int(sw * h / sh)), int(h))
    try:
        img = pygame.transform.smoothscale(src, size)
    except Exception:
        img = pygame.transform.scale(src, size)
    _BRAND_CACHE[key] = img
    return img


def set_window_icon():
    """Pencere / görev çubuğu ikonu. (.exe dosyasının kendi ikonu ayrıdır:
    PyInstaller --icon assets/arena_bonk.ico, bkz. build_exe.bat)"""
    try:
        ic = brand_image("icon")
        if ic is not None:
            pygame.display.set_icon(pygame.transform.smoothscale(ic, (64, 64)))
    except Exception:
        pass


class Display:
    """Oyun hep 1280x720'ye çizilir, sonra pencereye ölçeklenir.

    ÖLÇEKLEME NEREDE YAPILIYOR — bu, kare süresinin en büyük tek kalemiydi:
    eskiden her karede pygame.transform.smoothscale ile 1280x720 görüntü
    CPU'da pencere boyutuna büyütülüyordu. 1080p tam ekranda bu TEK BAŞINA
    8-14 ms, yani oyun ne kadar hızlı çizilirse çizilsin üst sınır ~60 FPS
    oluyordu. (Gözle görülmeyen bir maliyet: ölçekleme oyun kodunda değil,
    ekrana basma adımındaydı.)

    Artık SDL'in kendi ölçekleyicisi (pygame.SCALED) kullanılıyor: büyütmeyi
    ekran kartı yapıyor, CPU'nun işi yalnızca 1:1 bir kopya. Sürücü SCALED'i
    kabul etmezse eski yola düşülüyor; orada da smoothscale yerine hızlı
    ölçekleme kullanılıyor.
    """

    def __init__(self, save):
        self.save = save
        self.fullscreen = bool(save.data.get("settings", {}).get("fullscreen", False))
        self.scaled_mode = False
        set_window_icon()           # set_mode'dan ÖNCE: Windows ilk ikonu buradan alır
        self.screen = self._make_screen()
        pygame.display.set_caption(f"{GAME_TITLE}  v{GAME_VERSION}")
        _BRAND_CACHE.clear()        # ekran açıldı: convert_alpha'lı sürümler yüklensin
        self.canvas = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        self.scale = 1.0
        self.offset = (0, 0)
        self.out_size = (VIRTUAL_W, VIRTUAL_H)
        # Kontrolcü etkinken ana döngü buraya sanal imleci yazar; None ise
        # fare kullanılır.
        self.pad_cursor = None
        self._compute_scale()

    def _make_screen(self, size=None):
        """Ekranı açar. Önce donanım ölçeklemeli (SCALED) kip denenir.

        vsync KAPALI: oyuncu Ayarlar'dan FPS sınırını 60'ın üstüne
        çıkarabilsin. vsync açık olsaydı sınır her hâlükârda ekranın
        tazeleme hızı olurdu.
        """
        flags = pygame.FULLSCREEN if self.fullscreen else pygame.RESIZABLE
        want = (0, 0) if self.fullscreen else (size or (VIRTUAL_W, VIRTUAL_H))
        try:
            sc = pygame.display.set_mode((VIRTUAL_W, VIRTUAL_H),
                                         flags | pygame.SCALED)
            self.scaled_mode = True
            return sc
        except Exception:
            self.scaled_mode = False
            return pygame.display.set_mode(want, flags)

    def _compute_scale(self):
        if self.scaled_mode:
            # SDL ölçekliyor: oyun için ekran tam olarak 1280x720.
            self.scale = 1.0
            self.offset = (0, 0)
            self.out_size = (VIRTUAL_W, VIRTUAL_H)
            return
        sw, sh = self.screen.get_size()
        sw, sh = max(sw, 1), max(sh, 1)
        scale = max(min(sw / VIRTUAL_W, sh / VIRTUAL_H), 0.1)
        self.scale = scale
        out_w, out_h = int(VIRTUAL_W * scale), int(VIRTUAL_H * scale)
        self.offset = ((sw - out_w) // 2, (sh - out_h) // 2)
        self.out_size = (out_w, out_h)

    def toggle_fullscreen(self):
        self.fullscreen = not self.fullscreen
        try:
            self.screen = self._make_screen()
        except Exception:
            self.fullscreen = not self.fullscreen
        # set_mode bazı sürücülerde imleci yeniden görünür yapıyor: gizle.
        try:
            pygame.mouse.set_visible(False)
        except Exception:
            pass
        self.save.data.setdefault("settings", {})["fullscreen"] = self.fullscreen
        self.save.save()
        self._compute_scale()

    def handle_resize(self, size):
        # SCALED kipinde boyutlandırmayı SDL kendi hallediyor; set_mode'u
        # yeniden çağırmak gereksiz (ve bazı sürücülerde pencereyi
        # titretiyor).
        if not self.fullscreen and not self.scaled_mode:
            try:
                self.screen = pygame.display.set_mode(size, pygame.RESIZABLE)
            except Exception:
                pass
        self._compute_scale()

    def present(self):
        if abs(self.scale - 1.0) < 1e-3 and self.offset == (0, 0):
            self.screen.blit(self.canvas, (0, 0))
        else:
            # Yedek yol (SCALED yok). smoothscale yerine HIZLI ölçekleme:
            # yumuşatma, kare başına milisaniyelerce sürüyordu.
            self.screen.fill((0, 0, 0))
            self.screen.blit(pygame.transform.scale(self.canvas, self.out_size),
                             self.offset)
        pygame.display.flip()

    def virtual_mouse(self):
        # Kontrolcü etkinse imleç ondan gelir (bkz. App.run_loop).
        if self.pad_cursor is not None:
            return self.pad_cursor
        mx, my = pygame.mouse.get_pos()
        if self.scaled_mode:
            # SCALED kipinde SDL fare konumunu zaten sanal çözünürlüğe
            # çeviriyor.
            return (float(mx), float(my))
        vx = (mx - self.offset[0]) / self.scale if self.scale else 0
        vy = (my - self.offset[1]) / self.scale if self.scale else 0
        return (vx, vy)


# =====================================================================
# DÜNYA ZEMİNİ  ·  KÜÇÜK HARİTA
# ---------------------------------------------------------------------
# Zemin, kameranın gördüğü dikdörtgen kadar çizilir. Dünya 3x3 hücreden
# oluştuğu için hücre sınırları daha kalın çizgiyle belirtilir; oyuncu
# haritanın neresinde olduğunu bir bakışta anlar.
# =====================================================================

# Her bölgenin (normal arena / cehennem) kendi zemin paleti var.
BIOME_STYLE = {
    "arena": {
        "top": (22, 25, 42), "bottom": (11, 13, 24),
        "grid": (255, 255, 255, 7), "cell": (120, 150, 255, 26),
        "decal": (90, 120, 200), "wall": (92, 104, 150),
        "name": "ARENA",
        # 1. HARİTA SÜSLEMELERİ (bkz. _decorate_arena_floor)
        "stone": (40, 45, 70),      # döşeme taşı
        "stone_lo": (24, 27, 45),   # taşın derz/gölge rengi
        "moss": (58, 104, 86),      # taş aralarındaki yosun
        "rune": (118, 158, 255),    # yerdeki mavi mühür/yazıt
        "sand": (74, 70, 92),       # dövüş alanının kum halkası
        "crystal": (126, 198, 255), # yerden çıkan kristal
    },
    "hell": {
        "top": (52, 15, 14), "bottom": (13, 5, 8),
        "grid": (255, 140, 90, 7), "cell": (255, 110, 70, 30),
        "decal": (150, 52, 32), "wall": (214, 92, 58),
        "name": "CEHENNEM",
        # CEHENNEM'e özel zemin süslemeleri (bkz. _decorate_hell_floor)
        "lava": (255, 116, 34), "lava_hot": (255, 206, 120),
        "rock": (34, 20, 22), "ash": (84, 60, 58),
    },
}

_FLOOR_CACHE = {}


def _decorate_arena_floor(surf, st, rnd):
    """1. HARİTANIN zeminini boyar.

    Arena eskiden düz bir degrade + rastgele lekelerden ibaretti; oyuncunun
    ilk (ve en uzun) oynadığı harita, oyunun en boş görünen yeri oluyordu.
    Artık gerçek bir dövüş meydanı: kırık taş döşeme, derzlerden fışkıran
    yosun, merkezde kadim bir mühür, dört köşede sütun kaideleri, yerden
    çıkan kristaller ve etrafa saçılmış moloz.

    CEHENNEM'deki kardeşi gibi bunların hepsi zemin ÖNBELLEĞİNE BİR KEZ
    çizilir (her karede değil), bu yüzden detay bedavaya gelir. Canlı olan
    tek katman draw_world_floor() içindeki _draw_arena_air().
    """
    stone, stone_lo = st["stone"], st["stone_lo"]
    moss, rune = st["moss"], st["rune"]
    sand, crystal = st["sand"], st["crystal"]
    W, H = ARENA_RECT.w, ARENA_RECT.h

    # --- KIRIK TAŞ DÖŞEME ---------------------------------------------
    # Izgaraya oturan ama her biri biraz kaymış/dönmüş taşlar: dümdüz bir
    # fayans deseni yerine yıllanmış, oturmuş bir meydan hissi.
    TILE = 104
    for gy in range(-1, H // TILE + 2):
        for gx in range(-1, W // TILE + 2):
            if rnd.random() < 0.09:
                continue                      # eksik/kırılmış taş
            cx = gx * TILE + TILE * 0.5 + rnd.uniform(-3, 3)
            cy = gy * TILE + TILE * 0.5 + rnd.uniform(-3, 3)
            # Bazı taşlar iki kat geniş: tek tip kare fayans hissi olmasın.
            wide = rnd.random() < 0.16
            hw = TILE * (0.96 if wide else 0.5) - rnd.uniform(2.5, 5.0)
            hh = TILE * 0.5 - rnd.uniform(2.5, 5.0)
            ang = rnd.uniform(-0.022, 0.022)
            pts = rot_pts([(-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)],
                          ang, cx, cy)
            shade = rnd.uniform(0.80, 1.20)
            face = scale_col(stone, shade)
            # derz gölgesi (taşın altına düşen koyu bant)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.55),
                                [(x, y + 4) for x, y in pts])
            pygame.draw.polygon(surf, face, pts)
            # üst kenarda pah ışığı, alt kenarda gölge: taş kabarık dursun
            pygame.draw.line(surf, scale_col(face, 1.5), pts[0], pts[1], 2)
            pygame.draw.line(surf, scale_col(face, 1.28), pts[0], pts[3], 1)
            pygame.draw.line(surf, scale_col(stone_lo, 0.7), pts[3], pts[2], 2)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.85), pts, 1)
            # taşın üstünde çatlak
            if rnd.random() < 0.30:
                a = rnd.uniform(0, math.pi)
                ln = hw * rnd.uniform(0.5, 1.1)
                pygame.draw.line(surf, scale_col(stone_lo, 0.75),
                                 (cx - math.cos(a) * ln, cy - math.sin(a) * ln * 0.8),
                                 (cx + math.cos(a) * ln, cy + math.sin(a) * ln * 0.8), 2)
            # derzden fışkıran yosun
            if rnd.random() < 0.22:
                mx = cx + rnd.uniform(-hw, hw)
                my = cy + hh * rnd.choice((-1, 1))
                blit_disc(surf, mx, my, rnd.uniform(5, 13), moss,
                          int(rnd.uniform(40, 95)))

    # --- MERKEZDEKİ KADİM MÜHÜR ---------------------------------------
    # Dünyanın tam ortası: oyuncunun doğduğu yer. İki taş halka, aralarında
    # bir yazıt kuşağı ve ortada sekiz kollu bir yıldız.
    ccx, ccy = W * 0.5, H * 0.5
    R = 300
    blit_disc(surf, ccx, ccy, R * 1.06, sand, 60)
    # Halkalar taştan biraz AÇIK olsun: koyu kalınca zemine oyulmuş bir oluk
    # değil, üzerine çizilmiş siyah bir daire gibi duruyordu.
    for k, rad in ((0.52, R), (0.68, R * 0.82), (0.40, R * 0.55), (0.58, R * 0.40)):
        ring_aa(surf, ccx, ccy, rad, scale_col(rune, k), 3)
    # yazıt kuşağı: iki halka arasında eşit aralıklı kısa çentikler
    for i in range(72):
        a = i * math.tau / 72
        r0, r1 = R * 0.84, R * 0.98
        w = 3 if i % 6 == 0 else 1
        pygame.draw.line(surf, scale_col(rune, 0.70 if i % 6 == 0 else 0.42),
                         (ccx + math.cos(a) * r0, ccy + math.sin(a) * r0),
                         (ccx + math.cos(a) * r1, ccy + math.sin(a) * r1), w)
    # sekiz kollu yıldız
    star = []
    for i in range(16):
        a = -math.pi / 2 + i * math.pi / 8
        rr = R * (0.38 if i % 2 == 0 else 0.15)
        star.append((ccx + math.cos(a) * rr, ccy + math.sin(a) * rr))
    poly_aa(surf, star, scale_col(rune, 0.26))
    poly_edge(surf, star, scale_col(rune, 0.62), 2)
    circle_aa(surf, ccx, ccy, R * 0.09, scale_col(rune, 0.50))

    # --- KÖŞE SÜTUN KAİDELERİ -----------------------------------------
    # Dört köşede yıkılmış sütunların kaidesi: harita bir "yapı" gibi dursun.
    for (px, py) in ((W * 0.22, H * 0.22), (W * 0.78, H * 0.22),
                     (W * 0.22, H * 0.78), (W * 0.78, H * 0.78)):
        blit_disc(surf, px, py + 8, 74, (0, 0, 0), 70)
        for rr, k in ((66, 0.72), (52, 1.0), (40, 1.22)):
            pts = [(px + math.cos(i * math.tau / 8) * rr,
                    py + math.sin(i * math.tau / 8) * rr * 0.86) for i in range(8)]
            pygame.draw.polygon(surf, scale_col(stone, k), pts)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.9), pts, 2)
        ring_aa(surf, px, py, 30, scale_col(rune, 0.52), 2)
        # kırık sütun gövdesi: kaidenin üstünde kısa bir kütük
        for i in range(3):
            rr = 26 - i * 5
            pygame.draw.circle(surf, scale_col(stone, 1.0 + i * 0.12),
                               (int(px), int(py - i * 7)), rr)
        pygame.draw.circle(surf, scale_col(stone_lo, 1.1),
                           (int(px), int(py - 14)), 16, 2)

    # --- YERDEN ÇIKAN KRİSTALLER --------------------------------------
    for _ in range(46):
        cx, cy = rnd.uniform(60, W - 60), rnd.uniform(60, H - 60)
        if dist(cx, cy, ccx, ccy) < R * 1.1:
            continue                          # mührün üstüne kristal çıkmaz
        h = rnd.uniform(16, 38)
        w = h * rnd.uniform(0.26, 0.40)
        blit_disc(surf, cx, cy + 3, w * 2.2, (0, 0, 0), 70)
        add_glow(surf, cx, cy - h * 0.4, h * 1.5, crystal, 0.16)
        for sgn, k in ((-1, 0.62), (1, 1.0)):
            pts = [(cx, cy - h * k), (cx + sgn * w, cy - h * 0.34 * k),
                   (cx + sgn * w * 0.7, cy + 4), (cx - sgn * w * 0.2, cy + 4)]
            pygame.draw.polygon(surf, scale_col(crystal, 0.30 + 0.22 * k), pts)
            pygame.draw.polygon(surf, scale_col(crystal, 0.62), pts, 1)

    # --- MOLOZ / ÇAKIL -------------------------------------------------
    for _ in range(300):
        cx, cy = rnd.uniform(10, W - 10), rnd.uniform(10, H - 10)
        rad = rnd.uniform(2.5, 7.0)
        n = rnd.randint(5, 7)
        pts = [(cx + math.cos(i * math.tau / n) * rad * rnd.uniform(0.7, 1.25),
                cy + math.sin(i * math.tau / n) * rad * rnd.uniform(0.6, 1.0))
               for i in range(n)]
        pygame.draw.polygon(surf, scale_col(stone_lo, 0.85), [(x, y + 2) for x, y in pts])
        pygame.draw.polygon(surf, scale_col(stone, rnd.uniform(0.85, 1.25)), pts)

    # --- ESKİ DÖVÜŞLERİN İZLERİ ----------------------------------------
    # Zemine kazınmış uzun kılıç çizikleri: burada çok kan dökülmüş.
    for _ in range(46):
        x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
        a = rnd.uniform(0, math.tau)
        ln = rnd.uniform(26, 64)
        p1 = (x0 + math.cos(a) * ln, y0 + math.sin(a) * ln * 0.75)
        pygame.draw.line(surf, scale_col(stone_lo, 0.6), (x0, y0), p1, 2)

def _decorate_hell_floor(surf, st, rnd):
    """CEHENNEM zeminini boyar: lav çatlakları, magma gölleri, obsidyen kayalar.

    Bütün bunlar zemin ÖNBELLEĞİNE bir kez çizilir (her karede değil), bu
    yüzden istediğimiz kadar detay koyabiliyoruz. Canlı olan tek şey
    draw_world_floor() içindeki kor/ısı katmanı.
    """
    lava, hot = st["lava"], st["lava_hot"]
    rock, ash = st["rock"], st["ash"]
    W, H = ARENA_RECT.w, ARENA_RECT.h

    # --- yanık kömür lekeleri (zemine derinlik verir) ---
    for _ in range(260):
        cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
        blit_disc(surf, cx, cy, rnd.uniform(18, 70), (10, 4, 6), int(rnd.uniform(18, 46)))

    # --- magma gölleri: dış hâle + akkor göbek + kabuk kenarı ---
    for _ in range(18):
        cx, cy = rnd.uniform(60, W - 60), rnd.uniform(60, H - 60)
        rad = rnd.uniform(44, 112)
        pts = []
        n = rnd.randint(8, 12)
        for i in range(n):
            a = i * math.tau / n
            rr = rad * rnd.uniform(0.72, 1.18)
            pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr * 0.72))
        add_glow(surf, cx, cy, rad * 1.4, lava, 0.22)
        # koyu çukur -> soğumuş kabuk -> ergimiş göbek (üç katman)
        pygame.draw.polygon(surf, (24, 9, 10), [(px, py + 4) for px, py in pts])
        pygame.draw.polygon(surf, (56, 24, 20), pts)
        pygame.draw.polygon(surf, scale_col(lava, 0.68),
                            [(cx + (px - cx) * 0.78, cy + (py - cy) * 0.78) for px, py in pts])
        pygame.draw.polygon(surf, scale_col(hot, 0.78),
                            [(cx + (px - cx) * 0.34, cy + (py - cy) * 0.34) for px, py in pts])
        # kabuk üstünde soğumuş siyah adacıklar
        for _isl in range(rnd.randint(2, 4)):
            ia = rnd.uniform(0, math.tau)
            ir = rad * rnd.uniform(0.15, 0.55)
            blit_disc(surf, cx + math.cos(ia) * ir, cy + math.sin(ia) * ir * 0.7,
                      rnd.uniform(6, 16), (26, 12, 14), 230)
        pygame.draw.polygon(surf, (48, 20, 18), pts, 3)

    # --- lav çatlakları: dallanan, akkor damarlar ---
    for _ in range(58):
        x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
        ang = rnd.uniform(0, math.tau)
        for _branch in range(rnd.randint(1, 3)):
            bx, by, ba = x0, y0, ang + rnd.uniform(-0.9, 0.9)
            pts = [(bx, by)]
            for _seg in range(rnd.randint(4, 9)):
                ba += rnd.uniform(-0.55, 0.55)
                step = rnd.uniform(22, 54)
                bx += math.cos(ba) * step
                by += math.sin(ba) * step
                pts.append((bx, by))
            if len(pts) < 2:
                continue
            pygame.draw.lines(surf, (22, 8, 9), False, pts, 6)
            pygame.draw.lines(surf, scale_col(lava, 0.58), False, pts, 3)
            pygame.draw.lines(surf, scale_col(hot, 0.80), False, pts, 1)

    # --- obsidyen kayalar ve kemik parçaları ---
    for _ in range(150):
        cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
        rad = rnd.uniform(9, 26)
        pts = []
        n = rnd.randint(5, 7)
        for i in range(n):
            a = i * math.tau / n + rnd.uniform(-0.2, 0.2)
            rr = rad * rnd.uniform(0.7, 1.25)
            pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr * 0.8))
        pygame.draw.polygon(surf, (12, 6, 9), [(px + 3, py + 4) for px, py in pts])
        pygame.draw.polygon(surf, rock, pts)
        pygame.draw.polygon(surf, ash, pts, 1)
    for _ in range(70):
        cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
        a = rnd.uniform(0, math.tau)
        ln = rnd.uniform(14, 30)
        p0 = (cx - math.cos(a) * ln, cy - math.sin(a) * ln * 0.7)
        p1 = (cx + math.cos(a) * ln, cy + math.sin(a) * ln * 0.7)
        pygame.draw.line(surf, (186, 176, 158), p0, p1, 3)
        pygame.draw.circle(surf, (196, 186, 168), (int(p0[0]), int(p0[1])), 3)
        pygame.draw.circle(surf, (196, 186, 168), (int(p1[0]), int(p1[1])), 3)


def _build_floor(biome):
    """Bütün dünyanın zeminini BİR KEZ çizip saklar.

    Zemin (degrade + lekeler + ızgara + 3x3 hücre sınırları + duvar) her
    karede yeniden çizilirse pahalıya patlıyor. Bölge başına tek sefer
    hazırlanıp her karede yalnızca kameranın gördüğü parça kopyalanıyor.
    """
    st = BIOME_STYLE.get(biome, BIOME_STYLE["arena"])
    surf = pygame.Surface((ARENA_RECT.w, ARENA_RECT.h)).convert()

    # --- dikey degrade ---
    for y in range(ARENA_RECT.h):
        k = y / max(1, ARENA_RECT.h - 1)
        col = (int(lerp(st["top"][0], st["bottom"][0], k)),
               int(lerp(st["top"][1], st["bottom"][1], k)),
               int(lerp(st["top"][2], st["bottom"][2], k)))
        pygame.draw.line(surf, col, (0, y), (ARENA_RECT.w, y))

    # --- zemin lekeleri ---
    # ARENA'da taş döşeme zaten doku veriyor; lekeler orada yalnızca hafif
    # bir renk oynaması olarak kalsın (yoksa döşemeyi bulandırıyor).
    rnd = random.Random(sum(ord(c) for c in biome) * 7919)
    n_decal, a_lo, a_hi = (420, 10, 30) if biome == "hell" else (180, 6, 16)
    for _ in range(n_decal):
        dx = rnd.uniform(0, ARENA_RECT.w)
        dy = rnd.uniform(0, ARENA_RECT.h)
        dr = rnd.uniform(8, 44)
        blit_disc(surf, dx, dy, dr, st["decal"], int(rnd.uniform(a_lo, a_hi)))

    # --- BÖLGEYE ÖZEL ZEMİN SÜSLEMELERİ ---
    if biome == "hell":
        _decorate_hell_floor(surf, st, rnd)   # lav, magma gölü, obsidyen
    else:
        _decorate_arena_floor(surf, st, rnd)  # taş döşeme, mühür, kristal

    # --- ince ızgara + 3x3 hücre sınırları ---
    ov = pygame.Surface((ARENA_RECT.w, ARENA_RECT.h), pygame.SRCALPHA)
    step = 64
    for x in range(0, ARENA_RECT.w + 1, step):
        pygame.draw.line(ov, st["grid"], (x, 0), (x, ARENA_RECT.h))
    for y in range(0, ARENA_RECT.h + 1, step):
        pygame.draw.line(ov, st["grid"], (0, y), (ARENA_RECT.w, y))
    for i in range(1, WORLD_TILES_X):
        x = VIEW_RECT.w * i
        pygame.draw.line(ov, st["cell"], (x, 0), (x, ARENA_RECT.h), 3)
    for j in range(1, WORLD_TILES_Y):
        y = VIEW_RECT.h * j
        pygame.draw.line(ov, st["cell"], (0, y), (ARENA_RECT.w, y), 3)
    surf.blit(ov, (0, 0))

    # --- ÇIKILMAZ DÜNYA DUVARI ---
    # İçeriye doğru bir bant: koyu dolgu + eğik uyarı şeritleri + parlak kenar.
    # Oyuncu dünyanın bittiği yeri bir bakışta görsün.
    band = 20
    wcol = st["wall"]
    wall = pygame.Surface((ARENA_RECT.w, ARENA_RECT.h), pygame.SRCALPHA)
    edges = [pygame.Rect(0, 0, ARENA_RECT.w, band),
             pygame.Rect(0, ARENA_RECT.h - band, ARENA_RECT.w, band),
             pygame.Rect(0, 0, band, ARENA_RECT.h),
             pygame.Rect(ARENA_RECT.w - band, 0, band, ARENA_RECT.h)]
    for r in edges:
        pygame.draw.rect(wall, (*scale_col(wcol, 0.22), 235), r)
    # eğik şeritler
    stripe = (*scale_col(wcol, 0.55), 90)
    for r in edges:
        cl = wall.get_clip()
        wall.set_clip(r)
        x = r.left - r.height
        while x < r.right + r.height:
            pygame.draw.line(wall, stripe, (x, r.bottom), (x + r.height, r.top), 6)
            x += 26
        wall.set_clip(cl)
    # parlak iç kenar + en dış çizgi
    pygame.draw.rect(wall, (*wcol, 255), pygame.Rect(0, 0, ARENA_RECT.w, ARENA_RECT.h), width=3)
    pygame.draw.rect(wall, (*lighten(wcol, 0.25), 200),
                     pygame.Rect(band, band, ARENA_RECT.w - band * 2, ARENA_RECT.h - band * 2),
                     width=2)
    # köşe köşebentleri
    L = 90
    for (cx, cy, dx, dy) in ((0, 0, 1, 1), (ARENA_RECT.w, 0, -1, 1),
                             (0, ARENA_RECT.h, 1, -1), (ARENA_RECT.w, ARENA_RECT.h, -1, -1)):
        pygame.draw.line(wall, (*lighten(wcol, 0.5), 230), (cx, cy + dy * 2),
                         (cx + dx * L, cy + dy * 2), 5)
        pygame.draw.line(wall, (*lighten(wcol, 0.5), 230), (cx + dx * 2, cy),
                         (cx + dx * 2, cy + dy * L), 5)
    surf.blit(wall, (0, 0))
    return surf


def floor_surface(biome):
    surf = _FLOOR_CACHE.get(biome)
    if surf is None:
        surf = _build_floor(biome)
        _FLOOR_CACHE[biome] = surf
    return surf


# CEHENNEM havasında süzülen korlar. Dünya koordinatında bir kez üretilir;
# her karede yalnızca kameranın gördükleri çizilir ve zamanla yukarı süzülür.
_HELL_EMBERS = None


def hell_embers():
    global _HELL_EMBERS
    if _HELL_EMBERS is None:
        rnd = random.Random(90210)
        _HELL_EMBERS = [(rnd.uniform(0, ARENA_RECT.w), rnd.uniform(0, ARENA_RECT.h),
                         rnd.uniform(16, 46), rnd.uniform(1.4, 3.4),
                         rnd.uniform(0, math.tau))
                        for _ in range(900)]
    return _HELL_EMBERS


def _draw_hell_air(world, cam, t):
    """CEHENNEM'in canlı katmanı: yukarı süzülen korlar ve sıcaklık parıltısı."""
    span = 420.0
    for (ex, ey, spd, sz, ph) in hell_embers():
        # kor yukarı süzülür, tepeye varınca başa sarar
        yy = ey - (t * spd) % span
        if yy < cam.top - 20 or yy > cam.bottom + 20:
            continue
        xx = ex + math.sin(t * 0.8 + ph) * 22.0
        if xx < cam.left - 20 or xx > cam.right + 20:
            continue
        k = 1.0 - ((ey - yy) % span) / span
        # Renk kasten BASAMAKLI: blit_disc sprite önbelleği renge göre
        # anahtarlanıyor, her karede yeni bir ton üretilirse önbellek
        # sürekli dolup temizleniyor ve kare hızı düşüyor.
        blit_disc(world, xx, yy, sz * (0.45 + 0.55 * k),
                  (255, 150 + (int(70 * k) // 24) * 24, 60), int(70 + 130 * k))
    # ısı parıltısı: ekranın altından yukarı doğru sönen, nabız gibi atan örtü
    h = 170
    peak = 30 + 12 * math.sin(t * 1.3)
    heat = pygame.Surface((8, h), pygame.SRCALPHA)
    for i in range(h):
        k = (i / (h - 1)) ** 2          # aşağı indikçe güçlenir, kenarı belli olmaz
        pygame.draw.line(heat, (255, 92, 40, int(peak * k)), (0, i), (8, i))
    world.blit(pygame.transform.scale(heat, (cam.w, h)), (cam.left, cam.bottom - h))


# ARENA havasında süzülen ışık zerreleri ("ateş böcekleri"). Cehennemin
# korları gibi dünya koordinatında bir kez üretilir; her karede yalnızca
# kameranın gördükleri çizilir.
_ARENA_MOTES = None


def arena_motes():
    global _ARENA_MOTES
    if _ARENA_MOTES is None:
        rnd = random.Random(31337)
        _ARENA_MOTES = [(rnd.uniform(0, ARENA_RECT.w), rnd.uniform(0, ARENA_RECT.h),
                         rnd.uniform(9, 26), rnd.uniform(1.1, 2.6),
                         rnd.uniform(0, math.tau))
                        for _ in range(620)]
    return _ARENA_MOTES


def _draw_arena_air(world, cam, t):
    """ARENA'nın canlı katmanı.

    1. harita, oyuncunun en çok vakit geçirdiği yer olmasına rağmen hiç
    hareket etmiyordu. Artık üç katman var:
      1) yavaşça yükselen ışık zerreleri (ateş böcekleri gibi),
      2) merkezdeki kadim mührün nabız gibi atan mavi hâlesi,
      3) haritanın üstünde ağır ağır kayan bulut gölgeleri.
    Üçü de ucuz: zerreler sadece kameranın içindekiler kadar çiziliyor.
    """
    span = 340.0
    for (ex, ey, spd, sz, ph) in arena_motes():
        yy = ey - (t * spd) % span
        if yy < cam.top - 16 or yy > cam.bottom + 16:
            continue
        xx = ex + math.sin(t * 0.55 + ph) * 16.0
        if xx < cam.left - 16 or xx > cam.right + 16:
            continue
        k = 1.0 - ((ey - yy) % span) / span
        tw = 0.45 + 0.55 * math.sin(t * 2.2 + ph)
        blit_disc(world, xx, yy, sz * (0.5 + 0.5 * k),
                  (150, 190 + (int(50 * k) // 25) * 25, 255),
                  int((40 + 120 * k) * tw))

    # --- merkezdeki mührün nefesi ---
    # DİKKAT: bu katman her karede çalışıyor. Büyük yarıçaplı parlama/disk
    # blit'leri (300+ px) kare süresinin en pahalı kalemi oluyor, bu yüzden
    # yalnızca mühür GERÇEKTEN görüş alanındayken ve ölçülü boyutlarda
    # çiziliyor.
    ccx = ARENA_RECT.left + ARENA_RECT.w * 0.5
    ccy = ARENA_RECT.top + ARENA_RECT.h * 0.5
    if cam.inflate(120, 120).collidepoint(ccx, ccy):
        pulse = 0.5 + 0.5 * math.sin(t * 1.1)
        add_glow(world, ccx, ccy, 190, (90, 140, 255), 0.11 + 0.07 * pulse)
        ph = (t * 0.28) % 1.0
        ring_aa(world, ccx, ccy, 300 * (0.55 + 0.45 * ph),
                scale_col((118, 158, 255), 0.30 * (1.0 - ph)), 2)


def draw_world_floor(world, cam, biome, t):
    """Kameranın gördüğü zemin parçasını dünya yüzeyine kopyalar."""
    world.blit(floor_surface(biome), cam.topleft, cam)
    if biome == "hell":
        _draw_hell_air(world, cam, t)
    else:
        _draw_arena_air(world, cam, t)


_VIGNETTE = None


def view_vignette():
    """KALDIRILDI (v3.17).

    Sahanın kenarlarını karartan dikdörtgen bir karartma vardı; ortası
    aydınlık, kenarları koyu olduğu için oyuncu "boğuluyor" hissi veriyordu.
    Oyuncunun görüş alanı zaten kamera ile sınırlı ve ekrandan çıkan
    yaratıklar ışınlanıyor (bkz. reposition_stragglers), yani karartmanın
    oynanışa katkısı da yoktu.

    Fonksiyon duruyor ama tamamen SAYDAM bir yüzey döndürüyor: çağıran yer
    (draw_run) tek satırda sadeleşsin diye değil, ileride yeniden açılmak
    istenirse tek yerden açılabilsin diye.
    """
    global _VIGNETTE
    if _VIGNETTE is None:
        _VIGNETTE = pygame.Surface(VIEW_RECT.size, pygame.SRCALPHA)
    return _VIGNETTE


# =====================================================================
# İMLEÇ  (v3.18)
# ---------------------------------------------------------------------
# Windows imleci tamamen GİZLİ (pygame.mouse.set_visible(False)); oyunun
# kendi nişangahı her ekranda çiziliyor. İki biçim var:
#
#   "aim"  — OYUN İÇİ nişangah: ortası boş halka, dört kertik, ince bir
#            merkez noktası. Ateş ederken kısa bir "geri tepme" ile açılır.
#   "ui"   — MENÜ / MARKET imleci: sivri uçlu klasik ok, ama oyunun kendi
#            renkleriyle ve kontürlü — Windows okunun yerine geçiyor.
#
# İmleç EN SON çizilir (her panelin, her kartın üstünde) ve asla gecikmez:
# doğrudan o karedeki fare konumunu kullanır.
# =====================================================================

def draw_cursor(surf, pos, kind="ui", t=0.0, hot=False):
    """Oyunun kendi imleci. pos sanal ekran koordinatıdır."""
    if not pos:
        return
    x, y = int(pos[0]), int(pos[1])
    if kind == "aim":
        R = 11
        col = (255, 255, 255)
        acc = (255, 90, 90) if hot else (120, 220, 255)
        pad = 22
        cs = pygame.Surface((R * 2 + pad, R * 2 + pad), pygame.SRCALPHA)
        c = R + pad // 2
        # dış halka (ince, kontürlü)
        pygame.draw.circle(cs, (8, 9, 14, 170), (c, c), R + 1, 3)
        pygame.draw.circle(cs, (*col, 225), (c, c), R, 2)
        # dört kertik
        for dx, dy in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            x0, y0 = c + dx * (R + 3), c + dy * (R + 3)
            x1, y1 = c + dx * (R + 9), c + dy * (R + 9)
            pygame.draw.line(cs, (8, 9, 14, 170), (x0, y0), (x1, y1), 4)
            pygame.draw.line(cs, (*acc, 235), (x0, y0), (x1, y1), 2)
        # merkez noktası
        pygame.draw.circle(cs, (8, 9, 14, 190), (c, c), 2)
        pygame.draw.circle(cs, (*acc, 255), (c, c), 1)
        surf.blit(cs, (x - c, y - c))
        return

    # ---- MENÜ OKU ----
    # Klasik ok biçimi, ama oyunun kendi kontürüyle: koyu bir gölge, koyu bir
    # çerçeve ve içinde açık gri -> beyaz degrade. Hem koyu panelde hem açık
    # kartta okunuyor.
    body = [(0, 0), (0, 15.5), (3.9, 12.0), (6.4, 17.6), (8.8, 16.5),
            (6.5, 11.0), (11.3, 10.6)]
    sh = [(x + px + 1.5, y + py + 1.5) for px, py in body]
    pts = [(x + px, y + py) for px, py in body]
    pygame.draw.polygon(surf, (6, 7, 13), sh)
    pygame.draw.polygon(surf, (14, 16, 26), [(px - 1, py - 1) for px, py in pts])
    pygame.draw.polygon(surf, (248, 250, 255), pts)
    # gövdenin sağ yarısına hafif bir gri: düz beyaz "yapıştırma" gibi durmasın
    pygame.draw.polygon(surf, (206, 212, 230),
                        [pts[0], pts[6], pts[5], pts[3], pts[4]])
    pygame.draw.lines(surf, (20, 22, 36), True, pts, 1)


MINIMAP_W = 196          # sağ üstteki küçük haritanın genişliği
BIGMAP_H_FRAC = 0.62     # büyük haritanın ekran yüksekliğine oranı


def minimap_rect(big=False):
    """Haritanın dikdörtgeni. big=True ise ekranın ortasında büyük hâli."""
    if big:
        mh = int(VIRTUAL_H * BIGMAP_H_FRAC)
        mw = int(mh * ARENA_RECT.w / ARENA_RECT.h)
        if mw > VIRTUAL_W - 200:
            mw = VIRTUAL_W - 200
            mh = int(mw * ARENA_RECT.h / ARENA_RECT.w)
        r = pygame.Rect(0, 0, mw, mh)
        r.center = (VIRTUAL_W // 2, VIRTUAL_H // 2 + 4)
        return r
    mw = MINIMAP_W
    mh = int(MINIMAP_W * ARENA_RECT.h / ARENA_RECT.w)
    return pygame.Rect(VIRTUAL_W - mw - 16, ARENA_MARGIN_TOP + 10, mw, mh)


def draw_minimap(surf, run, t, big=False):
    """Dünya haritası.

    Dünyanın tamamını, kameranın gördüğü çerçeveyi, düşmanları, patronları,
    portalları ve oyuncuyu gösterir.

    big=False : sağ üstteki küçük harita (her zaman açık)
    big=True  : M tuşuyla açılan, ekranın ortasındaki BÜYÜK harita. Aynı
                çizim kodu kullanılır; işaretler haritanın ölçeğiyle birlikte
                büyür (k çarpanı), böylece büyük haritada noktalar iğne başı
                kalmaz.
    """
    st = BIOME_STYLE.get(run.biome, BIOME_STYLE["arena"])
    rect = minimap_rect(big)
    # İşaretler haritayla doğru orantılı büyürse büyük haritada balon gibi
    # duruyor (2 px'lik bir yaratık 11 px'e çıkıyordu). Kök ölçek: harita 5
    # kat büyürken işaretler yalnızca ~2 kat büyüyor.
    k = max(1.0, (rect.w / float(MINIMAP_W)) ** 0.55)

    if big:
        # Büyük harita açıkken arkadaki saha karartılır ki harita okunsun.
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        pygame.draw.rect(dim, (4, 5, 11, 188), dim.get_rect())
        surf.blit(dim, (0, 0))
        add_glow(surf, rect.centerx, rect.centery, rect.w * 0.60,
                 st.get("wall", (70, 90, 150)), 0.10)

    bg = pygame.Surface((rect.w, rect.h), pygame.SRCALPHA)
    pygame.draw.rect(bg, (8, 9, 16, 236 if big else 210), bg.get_rect(),
                     border_radius=int(8 * (2 if big else 1)))
    surf.blit(bg, rect.topleft)

    sx = rect.w / ARENA_RECT.w
    sy = rect.h / ARENA_RECT.h

    def mp(x, y):
        return (rect.x + (x - ARENA_RECT.left) * sx, rect.y + (y - ARENA_RECT.top) * sy)

    # 3x3 hücre çizgileri
    for i in range(1, WORLD_TILES_X):
        x = rect.x + VIEW_RECT.w * i * sx
        pygame.draw.line(surf, (*st["wall"], 90), (x, rect.y + 2), (x, rect.bottom - 2), 1)
    for j in range(1, WORLD_TILES_Y):
        y = rect.y + VIEW_RECT.h * j * sy
        pygame.draw.line(surf, (*st["wall"], 90), (rect.x + 2, y), (rect.right - 2, y), 1)

    # toplanabilirler (çok soluk)
    for pu in run.pickups:
        if pu.kind == "coin":
            px, py = mp(pu.x, pu.y)
            surf.set_at((int(px), int(py)), (150, 130, 60))

    # düşmanlar
    for e in run.enemies:
        if not e.alive:
            continue
        px, py = mp(e.x, e.y)
        # Cehennem yaratıklarının kendi renkleri var — küçük haritada da onları göster.
        col = getattr(e, "color", None) or ENEMY_COLORS.get(e.kind, RED)
        pygame.draw.circle(surf, col, (int(px), int(py)),
                           max(1, int(k * (2 if e.kind != "elite" else 3))))

    # patronlar
    for b in run.bosses:
        if b.alive and not b.is_hidden():
            px, py = mp(b.x, b.y)
            pulse = 3 + math.sin(t * 6) * 1.2
            pygame.draw.circle(surf, (255, 90, 80), (int(px), int(py)),
                               max(2, int(k * (4 + pulse * 0.4))))
            pygame.draw.circle(surf, WHITE, (int(px), int(py)), max(1, int(k * 2)))

    # MIKNATIS — nadir eşya, küçük haritada nabız gibi atar ki kaçırılmasın
    for mg in run.magnets:
        px, py = mp(mg.x, mg.y)
        pulse = 0.5 + 0.5 * math.sin(t * 7)
        add_glow(surf, px, py, (16 + pulse * 8) * k, MAGNET_COLOR, 0.45 + pulse * 0.35)
        pygame.draw.circle(surf, MAGNET_COLOR, (int(px), int(py)), max(2, int(k * (4 + pulse * 2))))
    # SEVİYE TAŞI — mıknatıs kadar nadir, aynı biçimde göze sokulur
    for lv in run.level_drops:
        px, py = mp(lv.x, lv.y)
        pulse = 0.5 + 0.5 * math.sin(t * 7)
        add_glow(surf, px, py, (16 + pulse * 8) * k, LEVEL_COLOR, 0.45 + pulse * 0.35)
        pygame.draw.circle(surf, LEVEL_COLOR, (int(px), int(py)), max(2, int(k * (4 + pulse * 2))))
        pygame.draw.circle(surf, MAGNET_COLOR2, (int(px), int(py)), max(1, int(k * 2)))

    # hortum (küçük haritada dönen halka)
    for tn in run.tornados:
        px, py = mp(tn.x, tn.y)
        pygame.draw.circle(surf, TORNADO_COLOR, (int(px), int(py)), max(3, int(k * 5)),
                           max(1, int(k)))

    # market portalı
    # cehennem portalı
    if run.hell_portal is not None:
        px, py = mp(run.hell_portal.x, run.hell_portal.y)
        pulse = 0.5 + 0.5 * math.sin(t * 4)
        add_glow(surf, px, py, 22 * k, HELL_PORTAL_COLOR, 0.25 + pulse * 0.25)
        pygame.draw.circle(surf, HELL_PORTAL_COLOR, (int(px), int(py)),
                           max(3, int(k * 5)), max(2, int(k * 2)))

    # kameranın gördüğü alan
    cam = run.cam_rect()
    vr = pygame.Rect(mp(cam.left, cam.top), (cam.w * sx, cam.h * sy))
    pygame.draw.rect(surf, (235, 240, 255), vr, width=max(1, int(k)))

    # oyuncu
    p = run.player
    px, py = mp(p.x, p.y)
    pygame.draw.circle(surf, WHITE, (int(px), int(py)), max(2, int(k * 3)))
    pygame.draw.circle(surf, p.skin["color"], (int(px), int(py)), max(1, int(k * 2)))
    ax, ay = p.aim_dir
    pygame.draw.line(surf, WHITE, (px, py), (px + ax * 7 * k, py + ay * 7 * k),
                     max(1, int(k)))

    if big:
        # Büyük haritanın çerçevesi, köşebentleri ve başlığı
        edge = st.get("wall", (90, 110, 170))
        pygame.draw.rect(surf, lighten(edge, 0.30), rect.inflate(6, 6), width=2,
                         border_radius=16)
        for cxs in (-1, 1):
            for cys in (-1, 1):
                ox = rect.centerx + cxs * (rect.w / 2 + 3)
                oy = rect.centery + cys * (rect.h / 2 + 3)
                pygame.draw.line(surf, GOLD, (ox, oy), (ox - cxs * 22, oy), 3)
                pygame.draw.line(surf, GOLD, (ox, oy), (ox, oy - cys * 22), 3)
        # Başlık ve ipucu haritanın İÇİNDE: dışarıda HUD yazılarına biniyordu.
        head = ("CEHENNEM HARİTASI" if run.biome == "hell" else "ARENA HARİTASI")
        cap = pygame.Surface((rect.w, 30), pygame.SRCALPHA)
        pygame.draw.rect(cap, (6, 7, 14, 200), cap.get_rect())
        surf.blit(cap, (rect.x, rect.y))
        pygame.draw.line(surf, scale_col(GOLD, 0.6), (rect.x + 10, rect.y + 30),
                         (rect.right - 10, rect.y + 30), 1)
        draw_text(surf, head, (rect.x + 14, rect.y + 7), 17, GOLD, bold=True,
                  shadow=False)
        draw_text(surf, L("ui.map_info", run.waves.wave, len(run.enemies)),
                  (rect.right - 14, rect.y + 9), 12, TEXT_DIM, right=True, shadow=False)
        draw_text(surf, L("ui.map_close"), (rect.centerx, rect.bottom - 20), 12,
                  (150, 156, 184), center=True, shadow=False)

    # çerçeve + etiket
    pygame.draw.rect(surf, st["wall"], rect, width=2, border_radius=8)
    lab = st["name"]
    lw = text_width(lab, 10, True) + 12
    lr = pygame.Rect(rect.x + 6, rect.y - 9, int(lw), 16)
    ls = pygame.Surface(lr.size, pygame.SRCALPHA)
    pygame.draw.rect(ls, (10, 11, 20, 235), ls.get_rect(), border_radius=6)
    surf.blit(ls, lr.topleft)
    draw_text(surf, lab, (lr.centerx, lr.y + 2), 10, st["wall"], bold=True, center=True,
              shadow=False)


def draw_offscreen_markers(surf, run, cam, t):
    """Ekran dışındaki önemli hedefler için kenar okları (patron / portallar)."""
    marks = []
    for b in run.bosses:
        # GÖLGE PERDESİ açıkken patron küçük haritada da, kenar okunda da yoktur.
        if b.alive and not b.is_hidden():
            marks.append((b.x, b.y, (255, 90, 80), "skull"))
    if run.hell_portal is not None:
        marks.append((run.hell_portal.x, run.hell_portal.y, HELL_PORTAL_COLOR, "gem"))
    # MIKNATIS ekran dışında kalırsa kenarda oku görünsün.
    for mg in run.magnets:
        marks.append((mg.x, mg.y, MAGNET_COLOR, "magnet"))
    for lv in run.level_drops:
        marks.append((lv.x, lv.y, LEVEL_COLOR, "star"))
    for (wx, wy, col, icon) in marks:
        if cam.collidepoint(wx, wy):
            continue
        cx, cy = cam.centerx, cam.centery
        dx, dy = wx - cx, wy - cy
        l = math.hypot(dx, dy) or 1.0
        dx, dy = dx / l, dy / l
        ex = clamp(cx + dx * cam.w, cam.left + 30, cam.right - 30)
        ey = clamp(cy + dy * cam.h, cam.top + 30, cam.bottom - 30)
        sx, sy = world_to_screen(ex, ey, cam)
        add_glow(surf, sx, sy, 34, col, 0.28)
        pygame.draw.circle(surf, (12, 13, 22), (int(sx), int(sy)), 13)
        pygame.draw.circle(surf, col, (int(sx), int(sy)), 13, 2)
        draw_icon(surf, sx, sy, icon, col, 7)
        pygame.draw.polygon(surf, col, [(sx + dx * 20, sy + dy * 20),
                                        (sx + dx * 13 - dy * 6, sy + dy * 13 + dx * 6),
                                        (sx + dx * 13 + dy * 6, sy + dy * 13 - dx * 6)])


